INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X01','kor',4,'u6',ARRAY['K4-1-u6-C1','K4-1-u6-C54']::text[],'이 단원에서 배울 것을 계산 · 그래프 같은 다른 공부로 여긴다','말로 · 글로 표현하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X02','kor',4,'u6',ARRAY['K4-1-u6-C2','K4-1-u6-C12']::text[],'일어난 일(결과)만 말해도 듣는 사람이 까닭을 안다고 여긴다','왜 그렇게 되었나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X03','kor',4,'u6',ARRAY['K4-1-u6-C4','K4-1-u6-C5']::text[],'원인과 결과의 뜻을 거꾸로 안다','까닭 → 일어난 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X04','kor',4,'u6',ARRAY['K4-1-u6-C6','K4-1-u6-C21']::text[],'앞에 있었거나 함께 나온 상관없는 사실(요일 · 장소)을 원인으로 고른다','그 일을 일어나게 했나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X05','kor',4,'u6',ARRAY['K4-1-u6-C6','K4-1-u6-C16','K4-1-u6-C48']::text[],'결과를 원인 자리에 놓아 거꾸로 잇는다','무엇이 먼저였나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X06','kor',4,'u6',ARRAY['K4-1-u6-C7']::text[],'한 일은 원인이거나 결과 가운데 하나일 뿐이라고 여긴다','결과도 다시 원인이 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X07','kor',4,'u6',ARRAY['K4-1-u6-C8']::text[],'원인 뒤에 결과를 이을 자리에 「그런데」 · 「그리고」 같은 말을 쓴다','원인 먼저면 그래서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X08','kor',4,'u6',ARRAY['K4-1-u6-C9']::text[],'「왜냐하면」을 쓰고 「때문이다」로 맺지 않거나 「그래서」와 섞는다','왜냐하면 … 때문이다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X09','kor',4,'u6',ARRAY['K4-1-u6-C10']::text[],'원인을 반드시 먼저 말해야 하고 결과를 먼저 말하면 틀린다고 여긴다','두 순서 모두 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X10','kor',4,'u6',ARRAY['K4-1-u6-C11']::text[],'한 일에는 원인 하나 · 결과 하나만 있다고 여긴다','여럿일 수도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X11','kor',4,'u6',ARRAY['K4-1-u6-C13']::text[],'경험 말하기에는 아주 특별한 일만 골라야 한다고 여긴다','작은 일도 좋아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X12','kor',4,'u6',ARRAY['K4-1-u6-C13']::text[],'까닭과 일어난 일이 없는 사실(숫자 · 색깔 · 이름)을 말할 경험으로 고른다','왜 일어났는지 말할 수 있나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X13','kor',4,'u6',ARRAY['K4-1-u6-C14']::text[],'경험을 정리하며 그 일이 「왜」 일어났는지를 빼먹는다','왜 일어났나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X14','kor',4,'u6',ARRAY['K4-1-u6-C15']::text[],'일어난 차례를 뒤섞어 정리한다','먼저 일어난 일부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X15','kor',4,'u6',ARRAY['K4-1-u6-C17']::text[],'빠진 고리 자리에 앞뒤와 이어지지 않는 일을 넣는다','앞에서 뒤로 이어지나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X16','kor',4,'u6',ARRAY['K4-1-u6-C18']::text[],'경험을 말할 때 외운 것을 빠르게 쏟아 내거나 무조건 크게만 말한다','또박또박 알맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X17','kor',4,'u6',ARRAY['K4-1-u6-C19']::text[],'친구가 말하는 도중에 끼어들거나 딴 데를 보며 듣는다','얼굴을 보며 끝까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X18','kor',4,'u6',ARRAY['K4-1-u6-C20']::text[],'말하기를 길이 · 목소리 · 빠르기 하나로만 점검한다','여러 물음으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X19','kor',4,'u6',ARRAY['K4-1-u6-C22']::text[],'감각적 표현을 어려운 낱말이나 긴 문장으로 여긴다','몸으로 느낀 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X20','kor',4,'u6',ARRAY['K4-1-u6-C23','K4-1-u6-C24']::text[],'감각과 그 감각으로 느끼는 것을 엇갈리게 안다(소리를 촉각으로)','어느 몸으로 느꼈나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X21','kor',4,'u6',ARRAY['K4-1-u6-C25','K4-1-u6-C34','K4-1-u6-C52']::text[],'감각과 상관없는 말(이어 주는 말 · 수 · 때)을 감각적 표현으로 고른다','느낌이 떠오르나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X22','kor',4,'u6',ARRAY['K4-1-u6-C27']::text[],'감각적 표현을 쓰면 글이 짧아지거나 어려운 말이 늘어난다고 여긴다','생생해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X23','kor',4,'u6',ARRAY['K4-1-u6-C28']::text[],'감각적 표현은 느끼지 않은 것이라도 많이 넣을수록 좋다고 여긴다','알맞게 · 실제로 느낀 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X24','kor',4,'u6',ARRAY['K4-1-u6-C28','K4-1-u6-C23']::text[],'모습과 소리만 감각적 표현이라고 여겨 냄새 · 맛 · 촉감을 쓰지 않는다','다섯 감각 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X25','kor',4,'u6',ARRAY['K4-1-u6-C29']::text[],'같은 시를 읽고 느낌이 다르면 둘 가운데 하나는 틀렸다고 여긴다','저마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X26','kor',4,'u6',ARRAY['K4-1-u6-C29']::text[],'시에 대한 반응을 시의 표현과 상관없는 것(줄 수 · 종이)으로 말한다','표현을 근거로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X27','kor',4,'u6',ARRAY['K4-1-u6-C30']::text[],'시로 쓸 경험으로 몸으로 느낀 것이 없는 사실(수 · 날짜)을 고른다','느낌이 남은 장면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X28','kor',4,'u6',ARRAY['K4-1-u6-C31']::text[],'겪은 일만 적고 생각이나 느낌을 빼먹는다','느낌까지 이어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X29','kor',4,'u6',ARRAY['K4-1-u6-C32']::text[],'「많이」 · 「아침에」처럼 양이나 때만 더하고 감각적으로 바꾸었다고 여긴다','감각을 더해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X30','kor',4,'u6',ARRAY['K4-1-u6-C33']::text[],'문장 끝을 늘 같은 꼴(-었다)로만 맺는다','끝맺음도 바꿔요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X31','kor',4,'u6',ARRAY['K4-1-u6-C35','K4-1-u6-C36']::text[],'행과 연의 뜻을 서로 바꾸어 안다','한 줄 · 한 덩어리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X32','kor',4,'u6',ARRAY['K4-1-u6-C37']::text[],'강조할 말을 따로 행으로 나누지 않고 길게 늘이거나 연만 마구 만든다','따로 한 행으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X33','kor',4,'u6',ARRAY['K4-1-u6-C38']::text[],'장면이 바뀌어도 연을 나누지 않거나 아무 데서나 연을 나눈다','장면이 바뀌는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X34','kor',4,'u6',ARRAY['K4-1-u6-C39']::text[],'남이 자주 쓰는 표현이나 다른 시의 표현을 그대로 옮기는 것이 좋다고 여긴다','내가 느낀 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X35','kor',4,'u6',ARRAY['K4-1-u6-C40','K4-1-u6-C45']::text[],'고칠 점으로 감각적 표현이나 마음이 빠진 것 대신 엉뚱한 것(행 수 · 문장 길이)을 고른다','무엇이 빠졌나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X36','kor',4,'u6',ARRAY['K4-1-u6-C42']::text[],'글로 쓸 내용을 정리하며 글자 수 · 쪽수 같은 상관없는 것을 넣는다','쓰는 데 도움이 되는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X37','kor',4,'u6',ARRAY['K4-1-u6-C43']::text[],'일기의 날씨는 「맑음 · 흐림」 한 낱말로만 써야 한다고 여긴다','그날의 느낌을 담아') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X38','kor',4,'u6',ARRAY['K4-1-u6-C44']::text[],'제목은 반드시 먼저 정해야 하거나 내용과 상관없어도 된다고 여긴다','다 쓴 뒤에 어울리게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X39','kor',4,'u6',ARRAY['K4-1-u6-C45']::text[],'경험 글은 있었던 일만 차례로 적으면 된다고 여긴다','보고 들은 것 · 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X40','kor',4,'u6',ARRAY['K4-1-u6-C47']::text[],'경험 글쓰기는 숙제일 뿐 나를 돌아보는 일과 상관없다고 여긴다','그날의 나를 담아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X41','kor',4,'u6',ARRAY['K4-1-u6-C46']::text[],'친구의 글을 듣고 감각적 표현 대신 길이 · 글씨만 말한다','어떤 감각을 살렸나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X42','kor',4,'u6',ARRAY['K4-1-u6-C48']::text[],'자연스럽게 이어지지 않는 두 카드도 억지로 원인과 결과로 잇는다','자연스러운가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X43','kor',4,'u6',ARRAY['K4-1-u6-C49']::text[],'한 대상은 한 가지 감각으로만 나타낼 수 있다고 여긴다','여러 감각으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X44','kor',4,'u6',ARRAY['K4-1-u6-C50']::text[],'시를 소개하며 감각적 표현과 상관없는 것(시집 두께 · 글자 수)을 말한다','어떤 감각으로 무엇을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X45','kor',4,'u6',ARRAY['K4-1-u6-C51']::text[],'「되어서」 · 「되었다」를 「되서」 · 「됬다」처럼 줄여 쓴다','되어 → 돼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X46','kor',4,'u6',ARRAY['K4-1-u6-C51']::text[],'「되어」로 바꿀 수 없는 자리(되고 · 되니)에도 「돼」를 쓴다','되어로 바꿔 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X47','kor',4,'u6',ARRAY['K4-1-u6-C53']::text[],'자음자를 놓이는 자리와 상관없이 늘 같은 크기 · 모양으로 쓴다','자리에 맞추어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X48','kor',4,'u6',ARRAY['K4-1-u6-C54']::text[],'원인과 결과 말하기와 감각적 표현 가운데 하나만 중요하거나, 지나간 일은 표현할 필요가 없다고 여긴다','말로 · 글로 남겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X49','kor',4,'u6',ARRAY['K4-1-u6-C41']::text[],'감각적 표현은 시에서만 쓰고 일기 같은 글에서는 쓰지 않는다고 여긴다','글에서도 살려 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u6-X50','kor',4,'u6',ARRAY['K4-1-u6-C26']::text[],'시 속 낱말의 겉뜻(별 · 소나기)만 보고 말하는 이가 겪은 장면을 엉뚱하게 떠올린다','실제 장면은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_basic#1','kor',4,1,'u6','L02','g4_1_kor_u6_L02_basic','lesson_basic','K4-1-u6-C1',1,'mc','auto','「경험을 표현해요」 단원에서 배우는 두 가지를 바르게 고른 것은 무엇인가요?',ARRAY['K4-1-u6-X01']::text[],false,'{"seq":1,"concept":"K4-1-u6-C1","difficulty":1,"kind":"mc","stem":"「경험을 표현해요」 단원에서 배우는 두 가지를 바르게 고른 것은 무엇인가요?","options":[{"t":"원인과 결과를 생각하며 경험 말하기와 감각적 표현으로 경험 나타내기","correct":true},{"t":"분수의 덧셈과 막대그래프 그리기","mis":"K4-1-u6-X01"},{"t":"노래 부르기와 줄넘기","mis":"K4-1-u6-X01"},{"t":"받아쓰기와 낱말 외우기","mis":"K4-1-u6-X01"}],"explanation":["말로 전하기","글로 남기기","원인과 결과 · 감각적 표현"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_basic#2','kor',4,1,'u6','L02','g4_1_kor_u6_L02_basic','lesson_basic','K4-1-u6-C4',1,'mc','auto','「원인」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X03','K4-1-u6-X04']::text[],false,'{"seq":2,"concept":"K4-1-u6-C4","difficulty":1,"kind":"mc","stem":"「원인」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"어떤 일이 일어나게 만든 까닭","correct":true},{"t":"그 까닭으로 인해 일어난 일","mis":"K4-1-u6-X03"},{"t":"일이 끝난 뒤의 기분","mis":"K4-1-u6-X03"},{"t":"일이 일어난 곳의 이름","mis":"K4-1-u6-X04"}],"explanation":["왜 일어났나요?","그 까닭","원인이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_basic#3','kor',4,1,'u6','L02','g4_1_kor_u6_L02_basic','lesson_basic','K4-1-u6-C5',1,'mc','auto','「모래밭에 빠진 팽이」에서 다온이가 팽이를 힘껏 돌린 일의 결과는 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X04']::text[],false,'{"seq":3,"concept":"K4-1-u6-C5","difficulty":1,"kind":"mc","stem":"「모래밭에 빠진 팽이」에서 다온이가 팽이를 힘껏 돌린 일의 결과는 무엇인가요?","options":[{"t":"팽이가 모래밭으로 튕겨 나갔다","correct":true},{"t":"새 팽이를 자랑하고 싶었다","mis":"K4-1-u6-X05"},{"t":"쉬는 시간이 되었다","mis":"K4-1-u6-X04"},{"t":"친구들과 운동장에 나갔다","mis":"K4-1-u6-X04"}],"explanation":["힘껏 돌렸더니?","그래서 생긴 일","결과예요."],"asset":{"type":"passage","lines":["다온이는 새로 산 팽이를 자랑하고 싶어 학교에 가져갔다.","쉬는 시간에 친구들과 운동장에서 팽이를 돌렸다.","다온이가 팽이를 힘껏 돌리자 팽이가 모래밭으로 튕겨 나갔다.","팽이가 모래에 파묻혀 아무리 뒤져도 찾을 수 없었다."],"title":"모래밭에 빠진 팽이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_basic#4','kor',4,1,'u6','L02','g4_1_kor_u6_L02_basic','lesson_basic','K4-1-u6-C3',1,'mc','auto','「매미 소리 가득한 하굣길」에서 소리를 나타내어 장면을 생생하게 만든 말은 무엇인가요?',ARRAY['K4-1-u6-X21']::text[],false,'{"seq":4,"concept":"K4-1-u6-C3","difficulty":1,"kind":"mc","stem":"「매미 소리 가득한 하굣길」에서 소리를 나타내어 장면을 생생하게 만든 말은 무엇인가요?","options":[{"t":"맴맴","correct":true},{"t":"운동장을","mis":"K4-1-u6-X21"},{"t":"집으로","mis":"K4-1-u6-X21"},{"t":"수업을","mis":"K4-1-u6-X21"}],"explanation":["귀에 들리는 말","매미 소리","맴맴이에요."],"asset":{"type":"passage","lines":["수업을 마치고 운동장을 가로질러 집으로 갔다.","매미 소리가 맴맴 귀를 가득 채웠다.","뜨끈한 바닥에서 아지랑이가 일렁였다.","목덜미로 땀이 주르륵 흘렀다."],"title":"매미 소리 가득한 하굣길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_basic#5','kor',4,1,'u6','L02','g4_1_kor_u6_L02_basic','lesson_basic','K4-1-u6-C2',2,'mc','auto','친구가 진우의 말을 알아듣지 못한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X02','K4-1-u6-X04']::text[],false,'{"seq":5,"concept":"K4-1-u6-C2","difficulty":2,"kind":"mc","stem":"친구가 진우의 말을 알아듣지 못한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"급식을 못 먹게 된 원인을 말하지 않아서","correct":true},{"t":"문장이 너무 길어서","mis":"K4-1-u6-X02"},{"t":"진우가 웃으며 말해서","mis":"K4-1-u6-X02"},{"t":"친구가 급식을 좋아해서","mis":"K4-1-u6-X04"}],"explanation":["진우가 말한 것은?","일어난 일만","까닭이 빠졌어요."],"asset":{"type":"speech","turns":[{"who":"진우","text":"나 오늘 급식을 못 먹었어."},{"who":"친구","text":"응? 왜? 무슨 일이 있었던 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_basic#6','kor',4,1,'u6','L02','g4_1_kor_u6_L02_basic','lesson_basic','K4-1-u6-C6',2,'mc','auto','「모래밭에 빠진 팽이」에서 다온이가 팽이를 찾지 못한 원인은 무엇인가요?',ARRAY['K4-1-u6-X04','K4-1-u6-X05']::text[],false,'{"seq":6,"concept":"K4-1-u6-C6","difficulty":2,"kind":"mc","stem":"「모래밭에 빠진 팽이」에서 다온이가 팽이를 찾지 못한 원인은 무엇인가요?","options":[{"t":"팽이가 모래에 파묻혔기 때문이다","correct":true},{"t":"쉬는 시간이 짧기 때문이다","mis":"K4-1-u6-X04"},{"t":"팽이가 새것이기 때문이다","mis":"K4-1-u6-X04"},{"t":"팽이를 찾지 못했기 때문이다","mis":"K4-1-u6-X05"}],"explanation":["찾지 못하게 만든 것은?","모래","파묻혔어요."],"asset":{"type":"passage","lines":["다온이는 새로 산 팽이를 자랑하고 싶어 학교에 가져갔다.","쉬는 시간에 친구들과 운동장에서 팽이를 돌렸다.","다온이가 팽이를 힘껏 돌리자 팽이가 모래밭으로 튕겨 나갔다.","팽이가 모래에 파묻혀 아무리 뒤져도 찾을 수 없었다."],"title":"모래밭에 빠진 팽이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_basic#7','kor',4,1,'u6','L02','g4_1_kor_u6_L02_basic','lesson_basic','K4-1-u6-C6',2,'match','auto','「모래밭에 빠진 팽이」에서 원인과 그 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K4-1-u6-C6","difficulty":2,"kind":"match","stem":"「모래밭에 빠진 팽이」에서 원인과 그 결과를 알맞게 이으세요.","pairs":[{"l":"새 팽이를 자랑하고 싶었다","r":"팽이를 학교에 가져갔다"},{"l":"팽이를 힘껏 돌렸다","r":"팽이가 모래밭으로 튕겨 나갔다"},{"l":"팽이가 모래에 파묻혔다","r":"팽이를 찾지 못했다"}],"mis":"K4-1-u6-X05","explanation":["먼저 있었던 일","그 뒤에 생긴 일","하나씩 이어요."],"asset":{"type":"passage","lines":["다온이는 새로 산 팽이를 자랑하고 싶어 학교에 가져갔다.","쉬는 시간에 친구들과 운동장에서 팽이를 돌렸다.","다온이가 팽이를 힘껏 돌리자 팽이가 모래밭으로 튕겨 나갔다.","팽이가 모래에 파묻혀 아무리 뒤져도 찾을 수 없었다."],"title":"모래밭에 빠진 팽이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_basic#8','kor',4,1,'u6','L02','g4_1_kor_u6_L02_basic','lesson_basic','K4-1-u6-C9',2,'ox','auto','「왜냐하면」으로 까닭을 말할 때는 「때문이다」로 끝맺는 것이 자연스러워요.',ARRAY['K4-1-u6-X08']::text[],false,'{"seq":8,"concept":"K4-1-u6-C9","difficulty":2,"kind":"ox","stem":"「왜냐하면」으로 까닭을 말할 때는 「때문이다」로 끝맺는 것이 자연스러워요.","answer":"O","reason_options":[{"t":"「왜냐하면」은 까닭을 밝힐 때 쓰고 「때문이다」와 짝을 이루기 때문에","correct":true},{"t":"「왜냐하면」 뒤에는 「그래서이다」로 끝맺어야 하기 때문에","mis":"K4-1-u6-X08"}],"mis":"K4-1-u6-X08","explanation":["왜냐하면 …","… 때문이다","짝을 이뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_basic#9','kor',4,1,'u6','L02','g4_1_kor_u6_L02_basic','lesson_basic','K4-1-u6-C7',2,'mc','auto','「곤충 도감을 빌려 읽었다 → ( ? ) → 아빠와 사슴벌레를 기르기 시작했다」에서 빈 곳에 알맞은 일은 무엇인가요?',ARRAY['K4-1-u6-X15','K4-1-u6-X14']::text[],false,'{"seq":9,"concept":"K4-1-u6-C7","difficulty":2,"kind":"mc","stem":"「곤충 도감을 빌려 읽었다 → ( ? ) → 아빠와 사슴벌레를 기르기 시작했다」에서 빈 곳에 알맞은 일은 무엇인가요?","options":[{"t":"사슴벌레를 기르고 싶어졌다","correct":true},{"t":"도감을 그대로 책꽂이에 꽂았다","mis":"K4-1-u6-X15"},{"t":"자전거를 타러 공원에 갔다","mis":"K4-1-u6-X15"},{"t":"사슴벌레가 튼튼하게 자랐다","mis":"K4-1-u6-X14"}],"explanation":["도감을 읽은 다음","기르기 전의 마음","결과가 다시 원인이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_basic#10','kor',4,1,'u6','L02','g4_1_kor_u6_L02_basic','lesson_basic','K4-1-u6-C11',3,'mc','auto','비가 많이 온 날 운동장에 물이 고이고, 우산이 뒤집히고, 신발이 젖었어요. 이 일을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X10','K4-1-u6-X05','K4-1-u6-X04']::text[],false,'{"seq":10,"concept":"K4-1-u6-C11","difficulty":3,"kind":"mc","stem":"비가 많이 온 날 운동장에 물이 고이고, 우산이 뒤집히고, 신발이 젖었어요. 이 일을 바르게 말한 것은 무엇인가요?","options":[{"t":"하나의 원인으로 여러 결과가 생겼다","correct":true},{"t":"원인 하나에는 결과도 꼭 하나만 생긴다","mis":"K4-1-u6-X10"},{"t":"물이 고인 것이 비가 온 원인이다","mis":"K4-1-u6-X05"},{"t":"신발이 젖은 것은 비와 상관없다","mis":"K4-1-u6-X04"}],"explanation":["원인은 무엇?","비","결과가 여럿이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_challenge#1','kor',4,1,'u6','L02','g4_1_kor_u6_L02_challenge','lesson_challenge','K4-1-u6-C10',2,'mc','auto','진우가 「체육복을 잃어버렸어.」를 먼저 말했어요. 이어서 까닭을 말할 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X07','K4-1-u6-X08']::text[],false,'{"seq":1,"concept":"K4-1-u6-C10","difficulty":2,"kind":"mc","stem":"진우가 「체육복을 잃어버렸어.」를 먼저 말했어요. 이어서 까닭을 말할 때 알맞은 것은 무엇인가요?","options":[{"t":"「왜냐하면 벤치에 두고 왔기 때문이야.」","correct":true},{"t":"「그래서 벤치에 두고 왔어.」","mis":"K4-1-u6-X05"},{"t":"「그런데 벤치에 두고 왔어.」","mis":"K4-1-u6-X07"},{"t":"「왜냐하면 벤치에 두고 와서 그래서야.」","mis":"K4-1-u6-X08"}],"explanation":["결과를 먼저 말했어요.","까닭은 뒤에","왜냐하면 … 때문이야"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_challenge#2','kor',4,1,'u6','L02','g4_1_kor_u6_L02_challenge','lesson_challenge','K4-1-u6-C4',2,'mc','auto','「바람이 세게 불었다. 그래서 우산이 뒤집혔다.」에서 원인은 무엇인가요?',ARRAY['K4-1-u6-X03','K4-1-u6-X04']::text[],false,'{"seq":2,"concept":"K4-1-u6-C4","difficulty":2,"kind":"mc","stem":"「바람이 세게 불었다. 그래서 우산이 뒤집혔다.」에서 원인은 무엇인가요?","options":[{"t":"바람이 세게 불었다","correct":true},{"t":"우산이 뒤집혔다","mis":"K4-1-u6-X03"},{"t":"우산을 펼쳤다","mis":"K4-1-u6-X04"},{"t":"바람과 우산 모두 결과이다","mis":"K4-1-u6-X03"}],"explanation":["그래서 앞","까닭","바람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_challenge#3','kor',4,1,'u6','L02','g4_1_kor_u6_L02_challenge','lesson_challenge','K4-1-u6-C10',3,'mc','auto','원인과 결과를 말하는 순서에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X09','K4-1-u6-X14']::text[],false,'{"seq":3,"concept":"K4-1-u6-C10","difficulty":3,"kind":"mc","stem":"원인과 결과를 말하는 순서에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"원인을 먼저 말해도 되고, 결과를 먼저 말하고 까닭을 뒤에 말해도 된다","correct":true},{"t":"원인은 꼭 맨 처음에 말해야 한다","mis":"K4-1-u6-X09"},{"t":"결과를 먼저 말하면 틀린 말이 된다","mis":"K4-1-u6-X09"},{"t":"차례와 상관없이 생각나는 대로 말하면 된다","mis":"K4-1-u6-X14"}],"explanation":["그래서","왜냐하면","두 순서 모두 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_challenge#4','kor',4,1,'u6','L02','g4_1_kor_u6_L02_challenge','lesson_challenge','K4-1-u6-C7',3,'mc','auto','「모래밭에 빠진 팽이」에서 결과이면서 또 다른 일의 원인인 것은 무엇인가요?',ARRAY['K4-1-u6-X06','K4-1-u6-X04']::text[],false,'{"seq":4,"concept":"K4-1-u6-C7","difficulty":3,"kind":"mc","stem":"「모래밭에 빠진 팽이」에서 결과이면서 또 다른 일의 원인인 것은 무엇인가요?","options":[{"t":"팽이가 모래에 파묻혔다","correct":true},{"t":"새 팽이를 자랑하고 싶었다","mis":"K4-1-u6-X06"},{"t":"팽이를 찾지 못했다","mis":"K4-1-u6-X06"},{"t":"쉬는 시간이 되었다","mis":"K4-1-u6-X04"}],"explanation":["앞일의 결과","뒷일의 원인","파묻혀서 못 찾았어요."],"asset":{"type":"passage","lines":["다온이는 새로 산 팽이를 자랑하고 싶어 학교에 가져갔다.","쉬는 시간에 친구들과 운동장에서 팽이를 돌렸다.","다온이가 팽이를 힘껏 돌리자 팽이가 모래밭으로 튕겨 나갔다.","팽이가 모래에 파묻혀 아무리 뒤져도 찾을 수 없었다."],"title":"모래밭에 빠진 팽이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_challenge#5','kor',4,1,'u6','L02','g4_1_kor_u6_L02_challenge','lesson_challenge','K4-1-u6-C2',3,'mc','auto','지호가 친구에게 다시 말할 때 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X02','K4-1-u6-X05','K4-1-u6-X07']::text[],false,'{"seq":5,"concept":"K4-1-u6-C2","difficulty":3,"kind":"mc","stem":"지호가 친구에게 다시 말할 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"「숙제는 미루고 늦게까지 놀았어. 그래서 엄마한테 혼났어.」","correct":true},{"t":"「엄마한테 혼났다니까.」","mis":"K4-1-u6-X02"},{"t":"「엄마한테 혼났어. 그래서 숙제를 미뤘어.」","mis":"K4-1-u6-X05"},{"t":"「아무튼 혼났어. 그런데 기분이 안 좋아.」","mis":"K4-1-u6-X07"}],"explanation":["친구가 궁금한 것은?","무슨 일이 있었는지","까닭을 함께 말해요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"나 어제 저녁에 엄마한테 혼났어."},{"who":"친구","text":"갑자기? 무슨 일이 있었는데?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_challenge#6','kor',4,1,'u6','L02','g4_1_kor_u6_L02_challenge','lesson_challenge','K4-1-u6-C12',3,'mc','auto','원인과 결과가 잘 드러나게 말하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X02','K4-1-u6-X16','K4-1-u6-X14']::text[],false,'{"seq":6,"concept":"K4-1-u6-C12","difficulty":3,"kind":"mc","stem":"원인과 결과가 잘 드러나게 말하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"왜 그런 일이 생겼는지 함께 말하고 「그래서」 · 「왜냐하면」을 넣는다","correct":true},{"t":"까닭은 빼고 일어난 일만 짧게 말한다","mis":"K4-1-u6-X02"},{"t":"무조건 큰 목소리로 빠르게 말한다","mis":"K4-1-u6-X16"},{"t":"생각나는 대로 차례를 뒤섞어 말한다","mis":"K4-1-u6-X14"}],"explanation":["까닭과 함께","이어 주는 말","차례대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_challenge#7','kor',4,1,'u6','L02','g4_1_kor_u6_L02_challenge','lesson_challenge','K4-1-u6-C11',3,'mc','auto','「물을 너무 많이 주었고, 볕이 드는 곳에 두지 않았다. 그래서 화초가 시들었다.」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X10','K4-1-u6-X05','K4-1-u6-X03']::text[],false,'{"seq":7,"concept":"K4-1-u6-C11","difficulty":3,"kind":"mc","stem":"「물을 너무 많이 주었고, 볕이 드는 곳에 두지 않았다. 그래서 화초가 시들었다.」를 바르게 말한 것은 무엇인가요?","options":[{"t":"두 가지 원인이 모여 하나의 결과가 생겼다","correct":true},{"t":"원인은 꼭 하나여야 하니 하나는 틀렸다","mis":"K4-1-u6-X10"},{"t":"화초가 시든 것이 물을 준 원인이다","mis":"K4-1-u6-X05"},{"t":"원인과 결과가 없는 문장이다","mis":"K4-1-u6-X03"}],"explanation":["까닭은 몇 가지?","물 · 볕","결과는 하나"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_challenge#8','kor',4,1,'u6','L02','g4_1_kor_u6_L02_challenge','lesson_challenge','K4-1-u6-C9',4,'essay','teacher','「나는 우산을 챙겨 갔어.」 뒤에 「왜냐하면 … 때문이다」로 까닭을 이어 쓰고, 같은 내용을 「그래서」를 넣어 원인을 먼저 말하는 순서로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u6-C9","difficulty":4,"kind":"essay","stem":"「나는 우산을 챙겨 갔어.」 뒤에 「왜냐하면 … 때문이다」로 까닭을 이어 쓰고, 같은 내용을 「그래서」를 넣어 원인을 먼저 말하는 순서로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 나는 우산을 챙겨 갔어. 왜냐하면 아침에 하늘이 잔뜩 흐렸기 때문이야. / 아침에 하늘이 잔뜩 흐렸어. 그래서 나는 우산을 챙겨 갔어.","scoring_points":["「왜냐하면 … 때문이다」를 짝지어 썼는가","「그래서」 앞에 원인을 썼는가","두 문장의 내용이 같은가"]},"explanation":["결과 먼저","원인 먼저","두 순서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_challenge#9','kor',4,1,'u6','L02','g4_1_kor_u6_L02_challenge','lesson_challenge','K4-1-u6-C2',4,'essay','teacher','친구가 진우의 말을 알아듣지 못한 까닭을 쓰고, 진우가 원인과 결과가 드러나게 다시 말한다면 어떻게 말하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u6-C2","difficulty":4,"kind":"essay","stem":"친구가 진우의 말을 알아듣지 못한 까닭을 쓰고, 진우가 원인과 결과가 드러나게 다시 말한다면 어떻게 말하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 진우는 급식을 못 먹었다는 결과만 말하고 그렇게 된 원인을 말하지 않았다. 「보건실에 다녀오느라 급식 시간을 놓쳤어. 그래서 급식을 못 먹었어.」처럼 말하면 좋다.","scoring_points":["원인을 말하지 않았다는 점을 썼는가","원인과 결과를 함께 넣어 다시 말했는가","이어 주는 말을 알맞게 썼는가"]},"explanation":["빠진 것은?","원인","그래서로 이어요."],"asset":{"type":"speech","turns":[{"who":"진우","text":"나 오늘 급식을 못 먹었어."},{"who":"친구","text":"응? 왜? 무슨 일이 있었던 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L02_challenge#10','kor',4,1,'u6','L02','g4_1_kor_u6_L02_challenge','lesson_challenge','K4-1-u6-C7',4,'essay','teacher','「곤충 도감을 빌려 읽었다」로 시작해, 결과가 다시 원인이 되는 일을 세 가지 더 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u6-C7","difficulty":4,"kind":"essay","stem":"「곤충 도감을 빌려 읽었다」로 시작해, 결과가 다시 원인이 되는 일을 세 가지 더 이어 쓰세요.","answer_guide":{"answer":"예: 곤충 도감을 빌려 읽었다 → 사슴벌레를 기르고 싶어졌다 → 주말에 사슴벌레를 데려왔다 → 날마다 먹이를 챙겨 주어 사슴벌레가 튼튼하게 자랐다.","scoring_points":["세 가지 일을 이어 썼는가","앞일이 뒷일의 까닭이 되게 이었는가","일어난 차례가 알맞은가"]},"explanation":["그다음 마음은?","그래서 한 일","사슬로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_basic#1','kor',4,1,'u6','L04','g4_1_kor_u6_L04_basic','lesson_basic','K4-1-u6-C13',1,'mc','auto','원인과 결과로 말하기 좋은 경험은 무엇인가요?',ARRAY['K4-1-u6-X12']::text[],false,'{"seq":1,"concept":"K4-1-u6-C13","difficulty":1,"kind":"mc","stem":"원인과 결과로 말하기 좋은 경험은 무엇인가요?","options":[{"t":"곤충 도감을 읽고 사슴벌레를 기르게 된 일","correct":true},{"t":"내가 좋아하는 숫자 세 가지","mis":"K4-1-u6-X12"},{"t":"교실 벽에 붙은 그림의 색깔","mis":"K4-1-u6-X12"},{"t":"우리 반 친구들의 이름 순서","mis":"K4-1-u6-X12"}],"explanation":["왜 그런 일이 생겼나요?","까닭과 일어난 일","또렷한 경험"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_basic#2','kor',4,1,'u6','L04','g4_1_kor_u6_L04_basic','lesson_basic','K4-1-u6-C14',1,'mc','auto','경험을 원인과 결과로 정리할 때 꼭 떠올려야 하는 것은 무엇인가요?',ARRAY['K4-1-u6-X13']::text[],false,'{"seq":2,"concept":"K4-1-u6-C14","difficulty":1,"kind":"mc","stem":"경험을 원인과 결과로 정리할 때 꼭 떠올려야 하는 것은 무엇인가요?","options":[{"t":"그 일이 왜 일어났는지","correct":true},{"t":"그날 입은 옷의 색깔","mis":"K4-1-u6-X13"},{"t":"그 일을 몇 글자로 말할지","mis":"K4-1-u6-X13"},{"t":"같은 날 짝이 먹은 반찬","mis":"K4-1-u6-X13"}],"explanation":["언제 · 어디서","어떤 일 · 왜","그래서 어떻게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_basic#3','kor',4,1,'u6','L04','g4_1_kor_u6_L04_basic','lesson_basic','K4-1-u6-C15',1,'mc','auto','「사슴벌레를 기르게 된 날」에서 가장 먼저 일어난 일은 무엇인가요?',ARRAY['K4-1-u6-X14']::text[],false,'{"seq":3,"concept":"K4-1-u6-C15","difficulty":1,"kind":"mc","stem":"「사슴벌레를 기르게 된 날」에서 가장 먼저 일어난 일은 무엇인가요?","options":[{"t":"도서관에서 곤충 도감을 빌려 읽었다","correct":true},{"t":"사슴벌레를 데려왔다","mis":"K4-1-u6-X14"},{"t":"톱밥을 갈아 주었다","mis":"K4-1-u6-X14"},{"t":"뿔이 반들반들해졌다","mis":"K4-1-u6-X14"}],"explanation":["시간의 흐름","맨 처음","도감이에요."],"asset":{"type":"passage","lines":["세라는 학교 도서관에서 곤충 도감을 빌려 읽었다.","사슴벌레 사진을 보고 직접 길러 보고 싶어졌다.","주말에 아빠와 곤충 가게에 가서 사슴벌레를 데려왔다.","매일 톱밥을 갈아 주고 먹이를 챙겨 주었다.","사슴벌레가 튼튼하게 자라 뿔이 더 반들반들해졌다."],"title":"사슴벌레를 기르게 된 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_basic#4','kor',4,1,'u6','L04','g4_1_kor_u6_L04_basic','lesson_basic','K4-1-u6-C19',1,'mc','auto','친구가 자기 경험을 말할 때 듣는 사람이 할 일은 무엇인가요?',ARRAY['K4-1-u6-X17']::text[],false,'{"seq":4,"concept":"K4-1-u6-C19","difficulty":1,"kind":"mc","stem":"친구가 자기 경험을 말할 때 듣는 사람이 할 일은 무엇인가요?","options":[{"t":"친구의 얼굴을 보며 끝까지 듣는다","correct":true},{"t":"말하는 도중에 끼어들어 내 경험을 말한다","mis":"K4-1-u6-X17"},{"t":"내가 말할 것만 생각하며 창밖을 본다","mis":"K4-1-u6-X17"},{"t":"친구가 말하는 동안 짝과 이야기한다","mis":"K4-1-u6-X17"}],"explanation":["누구를 보나요?","말하는 친구","끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_basic#5','kor',4,1,'u6','L04','g4_1_kor_u6_L04_basic','lesson_basic','K4-1-u6-C17',2,'mc','auto','「사슴벌레를 데려옴 → ( ? ) → 사슴벌레가 튼튼하게 자람」에서 빈 곳에 알맞은 일은 무엇인가요?',ARRAY['K4-1-u6-X15','K4-1-u6-X14']::text[],false,'{"seq":5,"concept":"K4-1-u6-C17","difficulty":2,"kind":"mc","stem":"「사슴벌레를 데려옴 → ( ? ) → 사슴벌레가 튼튼하게 자람」에서 빈 곳에 알맞은 일은 무엇인가요?","options":[{"t":"매일 톱밥을 갈고 먹이를 챙겨 줌","correct":true},{"t":"상자를 그대로 덮어 두기만 함","mis":"K4-1-u6-X15"},{"t":"사진을 한 장 찍어 두었음","mis":"K4-1-u6-X15"},{"t":"곤충 도감을 빌려 읽음","mis":"K4-1-u6-X14"}],"explanation":["튼튼하게 자라려면?","돌보는 일","꼭 필요한 고리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_basic#6','kor',4,1,'u6','L04','g4_1_kor_u6_L04_basic','lesson_basic','K4-1-u6-C16',2,'match','auto','「사슴벌레를 기르게 된 날」에서 원인과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-1-u6-C16","difficulty":2,"kind":"match","stem":"「사슴벌레를 기르게 된 날」에서 원인과 결과를 알맞게 이으세요.","pairs":[{"l":"곤충 도감을 읽었다","r":"사슴벌레를 기르고 싶어졌다"},{"l":"매일 톱밥과 먹이를 챙겼다","r":"사슴벌레가 튼튼하게 자랐다"},{"l":"주말에 곤충 가게에 갔다","r":"사슴벌레를 데려왔다"}],"mis":"K4-1-u6-X05","explanation":["앞에 있었던 일","뒤에 일어난 일","까닭과 결과"],"asset":{"type":"passage","lines":["세라는 학교 도서관에서 곤충 도감을 빌려 읽었다.","사슴벌레 사진을 보고 직접 길러 보고 싶어졌다.","주말에 아빠와 곤충 가게에 가서 사슴벌레를 데려왔다.","매일 톱밥을 갈아 주고 먹이를 챙겨 주었다.","사슴벌레가 튼튼하게 자라 뿔이 더 반들반들해졌다."],"title":"사슴벌레를 기르게 된 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_basic#7','kor',4,1,'u6','L04','g4_1_kor_u6_L04_basic','lesson_basic','K4-1-u6-C21',2,'mc','auto','「학교 앞 소식」에서 은행나무가 쓰러진 원인은 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X04']::text[],false,'{"seq":7,"concept":"K4-1-u6-C21","difficulty":2,"kind":"mc","stem":"「학교 앞 소식」에서 은행나무가 쓰러진 원인은 무엇인가요?","options":[{"t":"큰 태풍이 지나갔다","correct":true},{"t":"학생들이 옆 골목으로 돌아서 등교했다","mis":"K4-1-u6-X05"},{"t":"월요일 아침이었다","mis":"K4-1-u6-X04"},{"t":"인도가 막혔다","mis":"K4-1-u6-X05"}],"explanation":["쓰러지게 만든 것은?","태풍","원인이에요."],"asset":{"type":"passage","lines":["지난 주말 큰 태풍이 지나갔다.","학교 앞 은행나무가 쓰러져 인도가 막혔다.","월요일 아침, 학생들은 옆 골목으로 돌아서 등교했다."],"title":"학교 앞 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_basic#8','kor',4,1,'u6','L04','g4_1_kor_u6_L04_basic','lesson_basic','K4-1-u6-C13',2,'ox','auto','원인과 결과로 말할 경험은 아주 특별한 일만 골라야 해요.',ARRAY['K4-1-u6-X11']::text[],false,'{"seq":8,"concept":"K4-1-u6-C13","difficulty":2,"kind":"ox","stem":"원인과 결과로 말할 경험은 아주 특별한 일만 골라야 해요.","answer":"X","reason_options":[{"t":"작고 사소한 일이라도 까닭과 일어난 일이 또렷하면 좋은 경험이기 때문에","correct":true},{"t":"누구나 겪는 작은 일은 들을 만한 가치가 없기 때문에","mis":"K4-1-u6-X11"}],"mis":"K4-1-u6-X11","explanation":["특별해야 하나요?","작은 일도","까닭이 또렷하면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_basic#9','kor',4,1,'u6','L04','g4_1_kor_u6_L04_basic','lesson_basic','K4-1-u6-C18',2,'mc','auto','경험을 친구들에게 말할 때 알맞은 모습은 무엇인가요?',ARRAY['K4-1-u6-X16','K4-1-u6-X02']::text[],false,'{"seq":9,"concept":"K4-1-u6-C18","difficulty":2,"kind":"mc","stem":"경험을 친구들에게 말할 때 알맞은 모습은 무엇인가요?","options":[{"t":"「그래서」 · 「왜냐하면」을 넣어 또박또박 알맞은 크기로 말한다","correct":true},{"t":"외운 것을 빠르게 쏟아 낸다","mis":"K4-1-u6-X16"},{"t":"무조건 가장 큰 소리로 외친다","mis":"K4-1-u6-X16"},{"t":"까닭은 빼고 일어난 일만 말한다","mis":"K4-1-u6-X02"}],"explanation":["이어 주는 말","또박또박","알맞은 크기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_basic#10','kor',4,1,'u6','L04','g4_1_kor_u6_L04_basic','lesson_basic','K4-1-u6-C20',3,'mc','auto','경험 말하기를 스스로 점검하는 물음으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X18','K4-1-u6-X16']::text[],false,'{"seq":10,"concept":"K4-1-u6-C20","difficulty":3,"kind":"mc","stem":"경험 말하기를 스스로 점검하는 물음으로 알맞은 것은 무엇인가요?","options":[{"t":"일어난 순서에 맞게, 원인과 결과가 드러나게, 이어 주는 말을 써서 말했나요?","correct":true},{"t":"목소리만 컸으면 잘한 것인가요?","mis":"K4-1-u6-X18"},{"t":"길게만 말했으면 잘한 것인가요?","mis":"K4-1-u6-X18"},{"t":"가장 빨리 끝냈나요?","mis":"K4-1-u6-X16"}],"explanation":["순서","원인과 결과","이어 주는 말"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_challenge#1','kor',4,1,'u6','L04','g4_1_kor_u6_L04_challenge','lesson_challenge','K4-1-u6-C14',2,'mc','auto','「태민이의 연」에서 연이 미루나무에 걸린 일이 「왜 일어났나요?」에 대한 답으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X04','K4-1-u6-X05']::text[],false,'{"seq":1,"concept":"K4-1-u6-C14","difficulty":2,"kind":"mc","stem":"「태민이의 연」에서 연이 미루나무에 걸린 일이 「왜 일어났나요?」에 대한 답으로 알맞은 것은 무엇인가요?","options":[{"t":"바람이 갑자기 세게 불어 연줄이 끊어졌기 때문이다","correct":true},{"t":"토요일이었기 때문이다","mis":"K4-1-u6-X04"},{"t":"아저씨가 지나가셨기 때문이다","mis":"K4-1-u6-X05"},{"t":"강둑이 넓기 때문이다","mis":"K4-1-u6-X04"}],"explanation":["②를 봐요.","바람 · 연줄","그래서 걸렸어요."],"asset":{"type":"passage","lines":["① 토요일에 태민이는 강둑에서 연을 날렸다.","② 바람이 갑자기 세게 불어 연줄이 툭 끊어졌다.","③ 줄 끊긴 연은 날아가 높은 미루나무에 걸렸다.","④ 지나가던 이웃 아저씨가 긴 장대로 연을 내려 주셨다.","⑤ 태민이는 고마운 마음에 아저씨께 감사 쪽지를 썼다."],"title":"태민이의 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_challenge#2','kor',4,1,'u6','L04','g4_1_kor_u6_L04_challenge','lesson_challenge','K4-1-u6-C15',2,'mc','auto','「태민이의 연」을 시간의 흐름에 맞게 늘어놓은 것은 무엇인가요?',ARRAY['K4-1-u6-X14']::text[],false,'{"seq":2,"concept":"K4-1-u6-C15","difficulty":2,"kind":"mc","stem":"「태민이의 연」을 시간의 흐름에 맞게 늘어놓은 것은 무엇인가요?","options":[{"t":"연을 날림 → 연줄이 끊어짐 → 나무에 걸림 → 아저씨가 내려 주심 → 쪽지를 씀","correct":true},{"t":"연줄이 끊어짐 → 연을 날림 → 나무에 걸림 → 쪽지를 씀 → 아저씨가 내려 주심","mis":"K4-1-u6-X14"},{"t":"나무에 걸림 → 연줄이 끊어짐 → 연을 날림 → 아저씨가 내려 주심 → 쪽지를 씀","mis":"K4-1-u6-X14"},{"t":"쪽지를 씀 → 연을 날림 → 연줄이 끊어짐 → 나무에 걸림 → 아저씨가 내려 주심","mis":"K4-1-u6-X14"}],"explanation":["①부터","차례대로","⑤까지"],"asset":{"type":"passage","lines":["① 토요일에 태민이는 강둑에서 연을 날렸다.","② 바람이 갑자기 세게 불어 연줄이 툭 끊어졌다.","③ 줄 끊긴 연은 날아가 높은 미루나무에 걸렸다.","④ 지나가던 이웃 아저씨가 긴 장대로 연을 내려 주셨다.","⑤ 태민이는 고마운 마음에 아저씨께 감사 쪽지를 썼다."],"title":"태민이의 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_challenge#3','kor',4,1,'u6','L04','g4_1_kor_u6_L04_challenge','lesson_challenge','K4-1-u6-C16',3,'mc','auto','「태민이의 연」에서 결과이면서 또 다른 일의 원인인 것은 무엇인가요?',ARRAY['K4-1-u6-X06','K4-1-u6-X04']::text[],false,'{"seq":3,"concept":"K4-1-u6-C16","difficulty":3,"kind":"mc","stem":"「태민이의 연」에서 결과이면서 또 다른 일의 원인인 것은 무엇인가요?","options":[{"t":"줄 끊긴 연이 미루나무에 걸렸다","correct":true},{"t":"토요일에 강둑에서 연을 날렸다","mis":"K4-1-u6-X06"},{"t":"태민이가 아저씨께 감사 쪽지를 썼다","mis":"K4-1-u6-X06"},{"t":"강둑이 넓었다","mis":"K4-1-u6-X04"}],"explanation":["왜 걸렸나요?","걸려서 생긴 일은?","둘 다 있어요."],"asset":{"type":"passage","lines":["① 토요일에 태민이는 강둑에서 연을 날렸다.","② 바람이 갑자기 세게 불어 연줄이 툭 끊어졌다.","③ 줄 끊긴 연은 날아가 높은 미루나무에 걸렸다.","④ 지나가던 이웃 아저씨가 긴 장대로 연을 내려 주셨다.","⑤ 태민이는 고마운 마음에 아저씨께 감사 쪽지를 썼다."],"title":"태민이의 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_challenge#4','kor',4,1,'u6','L04','g4_1_kor_u6_L04_challenge','lesson_challenge','K4-1-u6-C21',3,'mc','auto','「3층 복도 소식」에서 학생들이 다른 계단으로 돌아서 간 원인으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X04']::text[],false,'{"seq":4,"concept":"K4-1-u6-C21","difficulty":3,"kind":"mc","stem":"「3층 복도 소식」에서 학생들이 다른 계단으로 돌아서 간 원인으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"3층 복도에 물이 고여 복도를 막았기 때문이다","correct":true},{"t":"아침이었기 때문이다","mis":"K4-1-u6-X04"},{"t":"학생들이 다른 계단을 좋아하기 때문이다","mis":"K4-1-u6-X04"},{"t":"교실이 3층에 있기 때문이다","mis":"K4-1-u6-X04"}],"explanation":["왜 돌아갔나요?","복도를 막았어요.","물이 고여서"],"asset":{"type":"passage","lines":["밤사이 3층 복도 창문이 열려 있었다.","새벽에 내린 비가 창문으로 들이쳐 복도에 물이 고였다.","아침에 3층 복도를 막아, 학생들은 다른 계단으로 돌아서 교실에 갔다."],"title":"3층 복도 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_challenge#5','kor',4,1,'u6','L04','g4_1_kor_u6_L04_challenge','lesson_challenge','K4-1-u6-C17',3,'mc','auto','「3층 복도 소식」에서 「창문이 열려 있었다 → ( ? ) → 복도를 막았다」의 빈 곳에 알맞은 일은 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X15']::text[],false,'{"seq":5,"concept":"K4-1-u6-C17","difficulty":3,"kind":"mc","stem":"「3층 복도 소식」에서 「창문이 열려 있었다 → ( ? ) → 복도를 막았다」의 빈 곳에 알맞은 일은 무엇인가요?","options":[{"t":"비가 창문으로 들이쳐 복도에 물이 고였다","correct":true},{"t":"학생들이 다른 계단으로 갔다","mis":"K4-1-u6-X05"},{"t":"새벽에 해가 떴다","mis":"K4-1-u6-X15"},{"t":"창문을 새로 칠했다","mis":"K4-1-u6-X15"}],"explanation":["창문이 열려서?","그래서 복도를 막았어요.","가운데 일"],"asset":{"type":"passage","lines":["밤사이 3층 복도 창문이 열려 있었다.","새벽에 내린 비가 창문으로 들이쳐 복도에 물이 고였다.","아침에 3층 복도를 막아, 학생들은 다른 계단으로 돌아서 교실에 갔다."],"title":"3층 복도 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_challenge#6','kor',4,1,'u6','L04','g4_1_kor_u6_L04_challenge','lesson_challenge','K4-1-u6-C19',3,'mc','auto','친구의 경험을 듣다가 까닭이 궁금해졌어요. 알맞게 행동한 것은 무엇인가요?',ARRAY['K4-1-u6-X17']::text[],false,'{"seq":6,"concept":"K4-1-u6-C19","difficulty":3,"kind":"mc","stem":"친구의 경험을 듣다가 까닭이 궁금해졌어요. 알맞게 행동한 것은 무엇인가요?","options":[{"t":"친구가 다 말한 뒤에 「왜 그렇게 되었어?」 하고 묻는다","correct":true},{"t":"친구 말을 끊고 바로 묻는다","mis":"K4-1-u6-X17"},{"t":"궁금해도 묻지 않고 딴생각을 한다","mis":"K4-1-u6-X17"},{"t":"친구 말이 끝나기 전에 내 경험을 말한다","mis":"K4-1-u6-X17"}],"explanation":["언제 묻나요?","다 들은 뒤에","얼굴을 보며"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_challenge#7','kor',4,1,'u6','L04','g4_1_kor_u6_L04_challenge','lesson_challenge','K4-1-u6-C13',3,'mc','auto','말할 경험을 고르지 못해 고민하는 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X11','K4-1-u6-X12','K4-1-u6-X02']::text[],false,'{"seq":7,"concept":"K4-1-u6-C13","difficulty":3,"kind":"mc","stem":"말할 경험을 고르지 못해 고민하는 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"「오늘 아침의 작은 일도 왜 일어났는지 말할 수 있으면 좋은 경험이야.」","correct":true},{"t":"「아주 특별한 여행 이야기가 없으면 말하지 마.」","mis":"K4-1-u6-X11"},{"t":"「좋아하는 색깔을 말하면 돼.」","mis":"K4-1-u6-X12"},{"t":"「까닭은 몰라도 일어난 일만 말하면 돼.」","mis":"K4-1-u6-X02"}],"explanation":["특별하지 않아도","까닭이 또렷하면","작은 일도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_challenge#8','kor',4,1,'u6','L04','g4_1_kor_u6_L04_challenge','lesson_challenge','K4-1-u6-C18',4,'essay','teacher','태민이가 되어 연이 나무에 걸린 경험을 「그래서」와 「왜냐하면 … 때문이다」를 모두 넣어 친구에게 말하듯 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u6-C18","difficulty":4,"kind":"essay","stem":"태민이가 되어 연이 나무에 걸린 경험을 「그래서」와 「왜냐하면 … 때문이다」를 모두 넣어 친구에게 말하듯 쓰세요.","answer_guide":{"answer":"예: 토요일에 강둑에서 연을 날렸는데 연이 미루나무에 걸렸어. 왜냐하면 바람이 갑자기 세게 불어서 연줄이 끊어졌기 때문이야. 다행히 이웃 아저씨가 장대로 내려 주셨어. 그래서 나는 감사 쪽지를 썼어.","scoring_points":["「그래서」를 알맞게 썼는가","「왜냐하면 … 때문이다」를 짝지어 썼는가","일어난 차례가 드러나는가"]},"explanation":["결과 먼저","까닭은 왜냐하면","그래서로 이어요."],"asset":{"type":"passage","lines":["① 토요일에 태민이는 강둑에서 연을 날렸다.","② 바람이 갑자기 세게 불어 연줄이 툭 끊어졌다.","③ 줄 끊긴 연은 날아가 높은 미루나무에 걸렸다.","④ 지나가던 이웃 아저씨가 긴 장대로 연을 내려 주셨다.","⑤ 태민이는 고마운 마음에 아저씨께 감사 쪽지를 썼다."],"title":"태민이의 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_challenge#9','kor',4,1,'u6','L04','g4_1_kor_u6_L04_challenge','lesson_challenge','K4-1-u6-C14',4,'essay','teacher','내 경험 하나를 골라 「언제 · 어디에서」, 「어떤 일」, 「왜 일어났나」, 「그래서 어떻게 되었나」로 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u6-C14","difficulty":4,"kind":"essay","stem":"내 경험 하나를 골라 「언제 · 어디에서」, 「어떤 일」, 「왜 일어났나」, 「그래서 어떻게 되었나」로 정리해 쓰세요.","answer_guide":{"answer":"예: 언제 · 어디에서 — 어제 저녁 집에서 / 어떤 일 — 동생과 쌓던 블록 탑이 무너졌다 / 왜 — 내가 맨 위에 큰 블록을 올렸기 때문이다 / 그래서 — 처음부터 다시 쌓으며 무거운 블록을 아래에 놓았다.","scoring_points":["네 가지를 모두 썼는가","「왜」에 알맞은 원인을 썼는가","「그래서」에 알맞은 결과를 썼는가"]},"explanation":["언제 · 어디서","왜","그래서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L04_challenge#10','kor',4,1,'u6','L04','g4_1_kor_u6_L04_challenge','lesson_challenge','K4-1-u6-C20',4,'essay','teacher','친구가 「캠핑 갔어. 재미있었어. 끝.」이라고 경험을 말했어요. 점검할 물음에 비추어 아쉬운 점 두 가지를 쓰고, 고칠 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u6-C20","difficulty":4,"kind":"essay","stem":"친구가 「캠핑 갔어. 재미있었어. 끝.」이라고 경험을 말했어요. 점검할 물음에 비추어 아쉬운 점 두 가지를 쓰고, 고칠 방법을 쓰세요.","answer_guide":{"answer":"예: 무슨 일이 왜 일어났는지 원인과 결과가 드러나지 않았고, 이어 주는 말도 쓰지 않았다. 캠핑에서 있었던 일을 차례대로 말하고 「그래서」 · 「왜냐하면」을 넣어 까닭을 함께 말하면 좋겠다.","scoring_points":["아쉬운 점 두 가지를 점검 물음에 맞게 썼는가","원인과 결과 · 이어 주는 말을 짚었는가","고칠 방법을 썼는가"]},"explanation":["순서","원인과 결과","이어 주는 말"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_basic#1','kor',4,1,'u6','L06','g4_1_kor_u6_L06_basic','lesson_basic','K4-1-u6-C22',1,'mc','auto','「감각적 표현」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X19','K4-1-u6-X21']::text[],false,'{"seq":1,"concept":"K4-1-u6-C22","difficulty":1,"kind":"mc","stem":"「감각적 표현」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"눈 · 귀 · 코 · 입 · 손으로 느낀 것을 생생하게 나타낸 말","correct":true},{"t":"뜻이 어려운 낱말을 골라 쓴 말","mis":"K4-1-u6-X19"},{"t":"문장을 길게 늘인 말","mis":"K4-1-u6-X19"},{"t":"수를 정확하게 센 말","mis":"K4-1-u6-X21"}],"explanation":["몸으로 느낀 것","생생하게","감각적 표현"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_basic#2','kor',4,1,'u6','L06','g4_1_kor_u6_L06_basic','lesson_basic','K4-1-u6-C24',1,'match','auto','표현과 그 표현에 담긴 감각을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K4-1-u6-C24","difficulty":1,"kind":"match","stem":"표현과 그 표현에 담긴 감각을 알맞게 이으세요.","pairs":[{"l":"붉게 물든 단풍","r":"눈에 보이는 모습"},{"l":"바스락거리는 낙엽","r":"귀에 들리는 소리"},{"l":"까슬까슬한 모래","r":"손에 닿는 느낌"}],"mis":"K4-1-u6-X20","explanation":["어느 몸으로 느꼈나요?","눈 · 귀 · 손","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_basic#3','kor',4,1,'u6','L06','g4_1_kor_u6_L06_basic','lesson_basic','K4-1-u6-C23',1,'mc','auto','「구수한」은 어떤 감각으로 느낀 것인가요?',ARRAY['K4-1-u6-X20']::text[],false,'{"seq":3,"concept":"K4-1-u6-C23","difficulty":1,"kind":"mc","stem":"「구수한」은 어떤 감각으로 느낀 것인가요?","options":[{"t":"후각(냄새)","correct":true},{"t":"시각(모양 · 색깔)","mis":"K4-1-u6-X20"},{"t":"청각(소리)","mis":"K4-1-u6-X20"},{"t":"촉각(닿는 느낌)","mis":"K4-1-u6-X20"}],"explanation":["구수한 무엇?","냄새","코로 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_basic#4','kor',4,1,'u6','L06','g4_1_kor_u6_L06_basic','lesson_basic','K4-1-u6-C25',1,'mc','auto','「수박 자르는 날」의 「쩌억」에 담긴 감각은 무엇인가요?',ARRAY['K4-1-u6-X20']::text[],false,'{"seq":4,"concept":"K4-1-u6-C25","difficulty":1,"kind":"mc","stem":"「수박 자르는 날」의 「쩌억」에 담긴 감각은 무엇인가요?","options":[{"t":"청각(소리)","correct":true},{"t":"후각(냄새)","mis":"K4-1-u6-X20"},{"t":"미각(맛)","mis":"K4-1-u6-X20"},{"t":"시각(모양 · 색깔)","mis":"K4-1-u6-X20"}],"explanation":["수박이 갈라질 때","무엇이 났나요?","소리예요."],"asset":{"type":"passage","lines":["칼끝이 닿자","쩌억,","빨간 여름이 갈라진다","까만 씨앗은","밤하늘에 남은 별","한 입 베어 물면","시원한 소나기가","입안에 쏟아진다"],"title":"수박 자르는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_basic#5','kor',4,1,'u6','L06','g4_1_kor_u6_L06_basic','lesson_basic','K4-1-u6-C25',2,'mc','auto','「수박 자르는 날」에서 감각적 표현을 바르게 모은 것은 무엇인가요?',ARRAY['K4-1-u6-X21']::text[],false,'{"seq":5,"concept":"K4-1-u6-C25","difficulty":2,"kind":"mc","stem":"「수박 자르는 날」에서 감각적 표현을 바르게 모은 것은 무엇인가요?","options":[{"t":"쩌억 · 빨간 · 까만 · 시원한","correct":true},{"t":"칼끝 · 한 입 · 베어","mis":"K4-1-u6-X21"},{"t":"닿자 · 물면 · 남은","mis":"K4-1-u6-X21"},{"t":"모두 · 그리고 · 그런데","mis":"K4-1-u6-X21"}],"explanation":["소리","색깔","시원한 느낌"],"asset":{"type":"passage","lines":["칼끝이 닿자","쩌억,","빨간 여름이 갈라진다","까만 씨앗은","밤하늘에 남은 별","한 입 베어 물면","시원한 소나기가","입안에 쏟아진다"],"title":"수박 자르는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_basic#6','kor',4,1,'u6','L06','g4_1_kor_u6_L06_basic','lesson_basic','K4-1-u6-C27',2,'mc','auto','감각적 표현을 쓰면 좋은 점은 무엇인가요?',ARRAY['K4-1-u6-X22']::text[],false,'{"seq":6,"concept":"K4-1-u6-C27","difficulty":2,"kind":"mc","stem":"감각적 표현을 쓰면 좋은 점은 무엇인가요?","options":[{"t":"대상을 직접 보고 듣는 것처럼 생생하게 느껴진다","correct":true},{"t":"글의 길이를 줄일 수 있다","mis":"K4-1-u6-X22"},{"t":"어려운 낱말을 많이 쓸 수 있다","mis":"K4-1-u6-X22"},{"t":"일이 일어난 까닭이 저절로 밝혀진다","mis":"K4-1-u6-X22"}],"explanation":["읽는 사람의 머릿속","장면이 떠올라요.","생생해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_basic#7','kor',4,1,'u6','L06','g4_1_kor_u6_L06_basic','lesson_basic','K4-1-u6-C26',2,'mc','auto','「수박 자르는 날」을 읽고 떠올릴 수 있는 장면은 무엇인가요?',ARRAY['K4-1-u6-X50']::text[],false,'{"seq":7,"concept":"K4-1-u6-C26","difficulty":2,"kind":"mc","stem":"「수박 자르는 날」을 읽고 떠올릴 수 있는 장면은 무엇인가요?","options":[{"t":"더운 여름날 큰 수박에 처음 칼을 대어 가르는 장면","correct":true},{"t":"밤하늘에서 별똥별이 떨어지는 장면","mis":"K4-1-u6-X50"},{"t":"소나기를 맞으며 집으로 뛰어가는 장면","mis":"K4-1-u6-X50"},{"t":"수박밭에서 수박을 따는 장면","mis":"K4-1-u6-X50"}],"explanation":["칼끝이 닿자","빨간 여름이 갈라진다","수박을 자르는 순간"],"asset":{"type":"passage","lines":["칼끝이 닿자","쩌억,","빨간 여름이 갈라진다","까만 씨앗은","밤하늘에 남은 별","한 입 베어 물면","시원한 소나기가","입안에 쏟아진다"],"title":"수박 자르는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_basic#8','kor',4,1,'u6','L06','g4_1_kor_u6_L06_basic','lesson_basic','K4-1-u6-C28',2,'ox','auto','감각적 표현은 많이 넣을수록 좋은 글이 돼요.',ARRAY['K4-1-u6-X23']::text[],false,'{"seq":8,"concept":"K4-1-u6-C28","difficulty":2,"kind":"ox","stem":"감각적 표현은 많이 넣을수록 좋은 글이 돼요.","answer":"X","reason_options":[{"t":"실제로 느낀 것을 알맞게 넣어야 살아나고, 억지로 많이 넣으면 오히려 어색하기 때문에","correct":true},{"t":"감각적 표현이 많을수록 무조건 생생해지기 때문에","mis":"K4-1-u6-X23"}],"mis":"K4-1-u6-X23","explanation":["많을수록?","억지로 넣으면","어색해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_basic#9','kor',4,1,'u6','L06','g4_1_kor_u6_L06_basic','lesson_basic','K4-1-u6-C29',2,'mc','auto','같은 시를 읽고 친구와 느낌이 달랐어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u6-X25','K4-1-u6-X26']::text[],false,'{"seq":9,"concept":"K4-1-u6-C29","difficulty":2,"kind":"mc","stem":"같은 시를 읽고 친구와 느낌이 달랐어요. 알맞은 생각은 무엇인가요?","options":[{"t":"같은 시도 사람마다 느낌이 다를 수 있으니 까닭을 들어 서로 나눈다","correct":true},{"t":"느낌이 다르면 둘 가운데 하나는 틀렸다","mis":"K4-1-u6-X25"},{"t":"선생님 느낌과 같아야 맞다","mis":"K4-1-u6-X25"},{"t":"시의 글자 수를 세어 많은 쪽이 맞다","mis":"K4-1-u6-X26"}],"explanation":["느낌은","저마다 달라요.","까닭을 들어 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_basic#10','kor',4,1,'u6','L06','g4_1_kor_u6_L06_basic','lesson_basic','K4-1-u6-C28',3,'mc','auto','감각적 표현을 쓸 때 주의할 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X24','K4-1-u6-X23','K4-1-u6-X49']::text[],false,'{"seq":10,"concept":"K4-1-u6-C28","difficulty":3,"kind":"mc","stem":"감각적 표현을 쓸 때 주의할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"모습과 소리뿐 아니라 냄새 · 맛 · 촉감도 실제로 느낀 대로 써 본다","correct":true},{"t":"모습과 소리만 쓰면 충분하다","mis":"K4-1-u6-X24"},{"t":"느끼지 않은 것도 그럴듯하게 많이 지어 넣는다","mis":"K4-1-u6-X23"},{"t":"감각적 표현은 시에만 쓰고 다른 글에는 쓰지 않는다","mis":"K4-1-u6-X49"}],"explanation":["다섯 감각","실제로 느낀 것","알맞게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
