INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_challenge#2','kor',4,1,'u6','L06','g4_1_kor_u6_L06_challenge','lesson_challenge','K4-1-u6-C23',2,'mc','auto','감각과 그 감각으로 느끼는 것을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-1-u6-X20']::text[],false,'{"seq":2,"concept":"K4-1-u6-C23","difficulty":2,"kind":"mc","stem":"감각과 그 감각으로 느끼는 것을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"미각 — 맛","correct":true},{"t":"후각 — 소리","mis":"K4-1-u6-X20"},{"t":"촉각 — 색깔","mis":"K4-1-u6-X20"},{"t":"청각 — 냄새","mis":"K4-1-u6-X20"}],"explanation":["미각은 입","맛","하나씩 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_challenge#3','kor',4,1,'u6','L06','g4_1_kor_u6_L06_challenge','lesson_challenge','K4-1-u6-C25',3,'mc','auto','「군고구마」에서 맛을 나타낸 표현은 무엇인가요?',ARRAY['K4-1-u6-X20','K4-1-u6-X21']::text[],false,'{"seq":3,"concept":"K4-1-u6-C25","difficulty":3,"kind":"mc","stem":"「군고구마」에서 맛을 나타낸 표현은 무엇인가요?","options":[{"t":"달큼한","correct":true},{"t":"노란","mis":"K4-1-u6-X20"},{"t":"폴폴","mis":"K4-1-u6-X20"},{"t":"껍질을","mis":"K4-1-u6-X21"}],"explanation":["혀끝에서","어떤 맛?","달큼해요."],"asset":{"type":"passage","lines":["호호 불어","껍질을 벗기면","노란 속살이","김을 폴폴 피운다","한 입 베어 물면","달큼한 겨울이","혀끝에서","사르르 녹는다"],"title":"군고구마"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_challenge#4','kor',4,1,'u6','L06','g4_1_kor_u6_L06_challenge','lesson_challenge','K4-1-u6-C27',3,'mc','auto','「수박에 칼을 대면 갈라진다.」보다 「칼끝이 닿자 쩌억, 빨간 여름이 갈라진다」가 더 좋은 까닭은 무엇인가요?',ARRAY['K4-1-u6-X22','K4-1-u6-X19']::text[],false,'{"seq":4,"concept":"K4-1-u6-C27","difficulty":3,"kind":"mc","stem":"「수박에 칼을 대면 갈라진다.」보다 「칼끝이 닿자 쩌억, 빨간 여름이 갈라진다」가 더 좋은 까닭은 무엇인가요?","options":[{"t":"소리와 색깔이 들어가 장면이 눈앞에 보이듯 떠오른다","correct":true},{"t":"문장이 더 짧아졌다","mis":"K4-1-u6-X22"},{"t":"어려운 낱말이 들어갔다","mis":"K4-1-u6-X19"},{"t":"수박을 자른 까닭이 드러났다","mis":"K4-1-u6-X22"}],"explanation":["쩌억","빨간","눈앞에 보이듯"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_challenge#5','kor',4,1,'u6','L06','g4_1_kor_u6_L06_challenge','lesson_challenge','K4-1-u6-C26',3,'mc','auto','「수박 자르는 날」의 「까만 씨앗은 / 밤하늘에 남은 별」에서 떠올릴 수 있는 모습은 무엇인가요?',ARRAY['K4-1-u6-X50']::text[],false,'{"seq":5,"concept":"K4-1-u6-C26","difficulty":3,"kind":"mc","stem":"「수박 자르는 날」의 「까만 씨앗은 / 밤하늘에 남은 별」에서 떠올릴 수 있는 모습은 무엇인가요?","options":[{"t":"빨간 수박 속에 까만 씨앗이 별처럼 콕콕 들어 있는 모습","correct":true},{"t":"밤하늘에 별이 가득 뜬 모습","mis":"K4-1-u6-X50"},{"t":"까만 밤에 수박을 먹는 모습","mis":"K4-1-u6-X50"},{"t":"씨앗을 땅에 심는 모습","mis":"K4-1-u6-X50"}],"explanation":["씨앗을 무엇에 빗댔나요?","별","수박 속 모습"],"asset":{"type":"passage","lines":["칼끝이 닿자","쩌억,","빨간 여름이 갈라진다","까만 씨앗은","밤하늘에 남은 별","한 입 베어 물면","시원한 소나기가","입안에 쏟아진다"],"title":"수박 자르는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_challenge#6','kor',4,1,'u6','L06','g4_1_kor_u6_L06_challenge','lesson_challenge','K4-1-u6-C29',3,'mc','auto','「수박 자르는 날」에 대한 반응을 알맞게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X26','K4-1-u6-X25']::text[],false,'{"seq":6,"concept":"K4-1-u6-C29","difficulty":3,"kind":"mc","stem":"「수박 자르는 날」에 대한 반응을 알맞게 말한 것은 무엇인가요?","options":[{"t":"「소나기라는 말에서 입안이 시원해지는 느낌이 들었어.」","correct":true},{"t":"「이 시는 여덟 줄이라서 좋았어.」","mis":"K4-1-u6-X26"},{"t":"「내 느낌과 다른 친구는 틀렸어.」","mis":"K4-1-u6-X25"},{"t":"「종이가 하얘서 좋았어.」","mis":"K4-1-u6-X26"}],"explanation":["시의 표현을 근거로","내 느낌","나눠요."],"asset":{"type":"passage","lines":["칼끝이 닿자","쩌억,","빨간 여름이 갈라진다","까만 씨앗은","밤하늘에 남은 별","한 입 베어 물면","시원한 소나기가","입안에 쏟아진다"],"title":"수박 자르는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_challenge#7','kor',4,1,'u6','L06','g4_1_kor_u6_L06_challenge','lesson_challenge','K4-1-u6-C28',3,'mc','auto','나래가 바다를 시로 쓰며 「파란 바다, 하얀 파도, 반짝이는 모래」처럼 눈에 보이는 것만 썼어요. 더 좋게 하려면 어떻게 해야 하나요?',ARRAY['K4-1-u6-X24','K4-1-u6-X19']::text[],false,'{"seq":7,"concept":"K4-1-u6-C28","difficulty":3,"kind":"mc","stem":"나래가 바다를 시로 쓰며 「파란 바다, 하얀 파도, 반짝이는 모래」처럼 눈에 보이는 것만 썼어요. 더 좋게 하려면 어떻게 해야 하나요?","options":[{"t":"철썩이는 소리, 짭조름한 냄새처럼 다른 감각도 실제로 느낀 대로 더해 본다","correct":true},{"t":"눈에 보이는 것을 더 많이 늘어놓는다","mis":"K4-1-u6-X24"},{"t":"느낌은 빼고 모습만 남긴다","mis":"K4-1-u6-X24"},{"t":"어려운 낱말로 바꾼다","mis":"K4-1-u6-X19"}],"explanation":["눈 말고","귀 · 코 · 혀 · 손","고르게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_challenge#8','kor',4,1,'u6','L06','g4_1_kor_u6_L06_challenge','lesson_challenge','K4-1-u6-C29',4,'essay','teacher','「수박 자르는 날」에서 가장 마음에 드는 표현 하나를 골라, 그 까닭과 함께 시를 읽고 든 내 느낌을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u6-C29","difficulty":4,"kind":"essay","stem":"「수박 자르는 날」에서 가장 마음에 드는 표현 하나를 골라, 그 까닭과 함께 시를 읽고 든 내 느낌을 쓰세요.","answer_guide":{"answer":"예: 「시원한 소나기가 입안에 쏟아진다」가 가장 마음에 든다. 수박을 한 입 먹을 때 물이 가득 터지는 느낌을 소나기에 빗대어 정말 시원하게 느껴졌기 때문이다. 시를 읽으니 여름에 가족과 수박을 먹던 날이 떠올랐다.","scoring_points":["시에 나온 표현을 골랐는가","고른 까닭을 썼는가","내 생각이나 느낌을 썼는가"]},"explanation":["어떤 표현?","왜?","내 느낌"],"asset":{"type":"passage","lines":["칼끝이 닿자","쩌억,","빨간 여름이 갈라진다","까만 씨앗은","밤하늘에 남은 별","한 입 베어 물면","시원한 소나기가","입안에 쏟아진다"],"title":"수박 자르는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_challenge#9','kor',4,1,'u6','L06','g4_1_kor_u6_L06_challenge','lesson_challenge','K4-1-u6-C27',4,'essay','teacher','「군고구마」에서 감각적 표현을 두 개 찾아 어떤 감각인지 쓰고, 감각적 표현이 없을 때와 비교하여 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u6-C27","difficulty":4,"kind":"essay","stem":"「군고구마」에서 감각적 표현을 두 개 찾아 어떤 감각인지 쓰고, 감각적 표현이 없을 때와 비교하여 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 「김을 폴폴 피운다」는 눈으로 본 시각, 「달큼한 겨울이」는 혀로 느낀 미각이다. 「군고구마를 먹었다」라고만 쓰면 장면이 잘 떠오르지 않지만, 감각적 표현이 있으니 따끈한 고구마를 직접 먹는 것처럼 생생하다.","scoring_points":["감각적 표현 두 개를 찾았는가","감각을 바르게 썼는가","좋은 점을 비교하여 썼는가"]},"explanation":["폴폴","달큼한","생생해요."],"asset":{"type":"passage","lines":["호호 불어","껍질을 벗기면","노란 속살이","김을 폴폴 피운다","한 입 베어 물면","달큼한 겨울이","혀끝에서","사르르 녹는다"],"title":"군고구마"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L06_challenge#10','kor',4,1,'u6','L06','g4_1_kor_u6_L06_challenge','lesson_challenge','K4-1-u6-C23',4,'essay','teacher','「비 오는 날」을 다섯 감각 가운데 세 가지로 나타내는 표현을 각각 쓰고, 어떤 감각인지 밝히세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u6-C23","difficulty":4,"kind":"essay","stem":"「비 오는 날」을 다섯 감각 가운데 세 가지로 나타내는 표현을 각각 쓰고, 어떤 감각인지 밝히세요.","answer_guide":{"answer":"예: 시각 — 회색 하늘에서 은빛 빗줄기가 쏟아진다. / 청각 — 창문을 두드리는 빗소리가 타닥타닥 들린다. / 촉각 — 우산 밖으로 내민 손등에 차가운 빗방울이 톡 떨어진다.","scoring_points":["세 가지 감각으로 썼는가","감각을 바르게 밝혔는가","실제로 느낄 만한 표현인가"]},"explanation":["보이는 것","들리는 것","닿는 것"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_basic#1','kor',4,1,'u6','L07','g4_1_kor_u6_L07_basic','lesson_basic','K4-1-u6-C30',1,'mc','auto','시로 쓰기 좋은 경험은 무엇인가요?',ARRAY['K4-1-u6-X27']::text[],false,'{"seq":1,"concept":"K4-1-u6-C30","difficulty":1,"kind":"mc","stem":"시로 쓰기 좋은 경험은 무엇인가요?","options":[{"t":"첫눈 온 아침 운동장을 밟은 일","correct":true},{"t":"우리 반 학생 수","mis":"K4-1-u6-X27"},{"t":"이번 달 달력의 날짜","mis":"K4-1-u6-X27"},{"t":"내 사물함 번호","mis":"K4-1-u6-X27"}],"explanation":["몸으로 느낀 것","또렷한 장면","첫눈"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
