INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_basic#3','kor',4,1,'u6','L07','g4_1_kor_u6_L07_basic','lesson_basic','K4-1-u6-C36',1,'mc','auto','시에서 행들이 모여 이룬 한 덩어리를 무엇이라고 하나요?',ARRAY['K4-1-u6-X31']::text[],false,'{"seq":3,"concept":"K4-1-u6-C36","difficulty":1,"kind":"mc","stem":"시에서 행들이 모여 이룬 한 덩어리를 무엇이라고 하나요?","options":[{"t":"연","correct":true},{"t":"행","mis":"K4-1-u6-X31"},{"t":"낱말","mis":"K4-1-u6-X31"},{"t":"문장","mis":"K4-1-u6-X31"}],"explanation":["여러 행","한 덩어리","연"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_basic#4','kor',4,1,'u6','L07','g4_1_kor_u6_L07_basic','lesson_basic','K4-1-u6-C32',1,'mc','auto','「운동장에 눈이 쌓였다.」를 감각적으로 바꾼 것은 무엇인가요?',ARRAY['K4-1-u6-X29']::text[],false,'{"seq":4,"concept":"K4-1-u6-C32","difficulty":1,"kind":"mc","stem":"「운동장에 눈이 쌓였다.」를 감각적으로 바꾼 것은 무엇인가요?","options":[{"t":"운동장에 뽀얀 눈이 소복소복 쌓였다.","correct":true},{"t":"운동장에 눈이 많이 쌓였다.","mis":"K4-1-u6-X29"},{"t":"아침에 운동장에 눈이 쌓였다.","mis":"K4-1-u6-X29"},{"t":"운동장에 눈이 또 쌓였다.","mis":"K4-1-u6-X29"}],"explanation":["색깔","모양","뽀얀 · 소복소복"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_basic#5','kor',4,1,'u6','L07','g4_1_kor_u6_L07_basic','lesson_basic','K4-1-u6-C31',2,'mc','auto','경험을 시로 쓰기 전에 내용을 정리하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X36','K4-1-u6-X28']::text[],false,'{"seq":5,"concept":"K4-1-u6-C31","difficulty":2,"kind":"mc","stem":"경험을 시로 쓰기 전에 내용을 정리하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"겪은 일 → 감각적 표현 → 생각이나 느낌","correct":true},{"t":"제목 → 글자 수 → 행 수","mis":"K4-1-u6-X36"},{"t":"겪은 일만 차례대로 적고 끝낸다","mis":"K4-1-u6-X28"},{"t":"생각이나 느낌 → 날짜 → 쪽수","mis":"K4-1-u6-X36"}],"explanation":["무슨 일?","어떻게 느꼈나?","마음은?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
