INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_basic#7','kor',4,1,'u6','L07','g4_1_kor_u6_L07_basic','lesson_basic','K4-1-u6-C37',2,'mc','auto','시에서 한 낱말을 힘주어 나타내고 싶을 때 알맞은 방법은 무엇인가요?',ARRAY['K4-1-u6-X32']::text[],false,'{"seq":7,"concept":"K4-1-u6-C37","difficulty":2,"kind":"mc","stem":"시에서 한 낱말을 힘주어 나타내고 싶을 때 알맞은 방법은 무엇인가요?","options":[{"t":"그 말만 따로 행으로 나눈다","correct":true},{"t":"연을 열 개 넘게 만든다","mis":"K4-1-u6-X32"},{"t":"문장을 한 줄로 길게 늘인다","mis":"K4-1-u6-X32"},{"t":"그 낱말을 지운다","mis":"K4-1-u6-X32"}],"explanation":["힘을 실으려면","따로 한 줄","행으로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_basic#8','kor',4,1,'u6','L07','g4_1_kor_u6_L07_basic','lesson_basic','K4-1-u6-C38',2,'mc','auto','시에서 연을 나누면 좋은 곳은 어디인가요?',ARRAY['K4-1-u6-X33']::text[],false,'{"seq":8,"concept":"K4-1-u6-C38","difficulty":2,"kind":"mc","stem":"시에서 연을 나누면 좋은 곳은 어디인가요?","options":[{"t":"말하려는 대상이나 장면이 바뀌는 곳","correct":true},{"t":"한 줄이 끝날 때마다","mis":"K4-1-u6-X33"},{"t":"글자 수가 열 자가 될 때마다","mis":"K4-1-u6-X33"},{"t":"아무 데서나 마음대로","mis":"K4-1-u6-X33"}],"explanation":["장면이 바뀌면","연을 나눠요.","덩어리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_basic#9','kor',4,1,'u6','L07','g4_1_kor_u6_L07_basic','lesson_basic','K4-1-u6-C40',2,'mc','auto','「어느 친구가 쓴 시」에서 가장 아쉬운 점은 무엇인가요?',ARRAY['K4-1-u6-X35']::text[],false,'{"seq":9,"concept":"K4-1-u6-C40","difficulty":2,"kind":"mc","stem":"「어느 친구가 쓴 시」에서 가장 아쉬운 점은 무엇인가요?","options":[{"t":"감각적 표현이 없어 장면이 떠오르지 않는다","correct":true},{"t":"겪은 일이 하나도 없다","mis":"K4-1-u6-X35"},{"t":"행이 너무 많다","mis":"K4-1-u6-X35"},{"t":"제목이 너무 길다","mis":"K4-1-u6-X35"}],"explanation":["눈이 왔다.","어떤 눈?","감각적 표현이 없어요."],"asset":{"type":"passage","lines":["오늘 눈이 왔다.","눈이 많이 왔다.","기분이 좋았다."],"title":"어느 친구가 쓴 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_basic#10','kor',4,1,'u6','L07','g4_1_kor_u6_L07_basic','lesson_basic','K4-1-u6-C39',3,'mc','auto','시를 쓸 때 나만의 표현을 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X34','K4-1-u6-X23']::text[],false,'{"seq":10,"concept":"K4-1-u6-C39","difficulty":3,"kind":"mc","stem":"시를 쓸 때 나만의 표현을 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"남이 자주 쓰는 말 대신 그때 내가 느낀 그대로를 떠올려 쓴다","correct":true},{"t":"잘 알려진 시에서 좋은 표현을 그대로 옮겨 쓴다","mis":"K4-1-u6-X34"},{"t":"누구나 쓰는 「눈처럼 하얀」 같은 말만 쓴다","mis":"K4-1-u6-X34"},{"t":"느낌이 떠오르지 않으면 감각적 표현을 아무거나 넣는다","mis":"K4-1-u6-X23"}],"explanation":["남의 말 말고","내가 느낀 것","새롭게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_challenge#1','kor',4,1,'u6','L07','g4_1_kor_u6_L07_challenge','lesson_challenge','K4-1-u6-C33',2,'mc','auto','「발을 디디니 소리가 났다.」를 감각적 표현과 끝맺음까지 바꾸어 쓴 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X30','K4-1-u6-X29']::text[],false,'{"seq":1,"concept":"K4-1-u6-C33","difficulty":2,"kind":"mc","stem":"「발을 디디니 소리가 났다.」를 감각적 표현과 끝맺음까지 바꾸어 쓴 것으로 알맞은 것은 무엇인가요?","options":[{"t":"한 발 내디디니 뽀드득, 새 발자국이 찍힌다","correct":true},{"t":"발을 디뎠다. 소리가 났다.","mis":"K4-1-u6-X30"},{"t":"발을 디디니 소리가 났었다.","mis":"K4-1-u6-X30"},{"t":"발을 디디니 소리가 많이 났다.","mis":"K4-1-u6-X29"}],"explanation":["어떤 소리?","뽀드득","끝맺음도 새롭게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_challenge#2','kor',4,1,'u6','L07','g4_1_kor_u6_L07_challenge','lesson_challenge','K4-1-u6-C35',2,'mc','auto','「첫눈」은 모두 몇 행으로 되어 있나요?',ARRAY['K4-1-u6-X31']::text[],false,'{"seq":2,"concept":"K4-1-u6-C35","difficulty":2,"kind":"mc","stem":"「첫눈」은 모두 몇 행으로 되어 있나요?","options":[{"t":"8행","correct":true},{"t":"1행","mis":"K4-1-u6-X31"},{"t":"2행","mis":"K4-1-u6-X31"},{"t":"8연","mis":"K4-1-u6-X31"}],"explanation":["한 줄씩","세어 봐요.","행은 줄"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_challenge#3','kor',4,1,'u6','L07','g4_1_kor_u6_L07_challenge','lesson_challenge','K4-1-u6-C37',3,'mc','auto','「첫눈」에서 「뽀얗게」와 「뽀드득」을 한 행에 하나씩 따로 쓴 까닭은 무엇인가요?',ARRAY['K4-1-u6-X32','K4-1-u6-X31']::text[],false,'{"seq":3,"concept":"K4-1-u6-C37","difficulty":3,"kind":"mc","stem":"「첫눈」에서 「뽀얗게」와 「뽀드득」을 한 행에 하나씩 따로 쓴 까닭은 무엇인가요?","options":[{"t":"눈의 빛깔과 밟는 소리를 힘주어 나타내려고","correct":true},{"t":"시를 길어 보이게 하려고","mis":"K4-1-u6-X32"},{"t":"연을 나누려고","mis":"K4-1-u6-X31"},{"t":"쓸 말이 떨어져서","mis":"K4-1-u6-X32"}],"explanation":["따로 한 행","힘이 실려요.","빛깔과 소리"],"asset":{"type":"passage","lines":["밤새 하늘이 밀가루를","체에 쳤나 보다","운동장이","뽀얗게","덮였다","한 발 내디디니","뽀드득","새 발자국이 찍힌다"],"title":"첫눈"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_challenge#4','kor',4,1,'u6','L07','g4_1_kor_u6_L07_challenge','lesson_challenge','K4-1-u6-C38',3,'mc','auto','「군고구마」를 두 연으로 나눈다면 어디에서 나누는 것이 가장 알맞은가요?',ARRAY['K4-1-u6-X33']::text[],false,'{"seq":4,"concept":"K4-1-u6-C38","difficulty":3,"kind":"mc","stem":"「군고구마」를 두 연으로 나눈다면 어디에서 나누는 것이 가장 알맞은가요?","options":[{"t":"「김을 폴폴 피운다」 다음","correct":true},{"t":"「호호 불어」 다음","mis":"K4-1-u6-X33"},{"t":"「혀끝에서」 다음","mis":"K4-1-u6-X33"},{"t":"연은 나누지 않아야 한다","mis":"K4-1-u6-X33"}],"explanation":["껍질 벗기기","한 입 먹기","장면이 바뀌는 곳"],"asset":{"type":"passage","lines":["호호 불어","껍질을 벗기면","노란 속살이","김을 폴폴 피운다","한 입 베어 물면","달큼한 겨울이","혀끝에서","사르르 녹는다"],"title":"군고구마"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_challenge#5','kor',4,1,'u6','L07','g4_1_kor_u6_L07_challenge','lesson_challenge','K4-1-u6-C40',3,'mc','auto','「소율이가 처음 쓴 시」를 고칠 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X29','K4-1-u6-X32','K4-1-u6-X35']::text[],false,'{"seq":5,"concept":"K4-1-u6-C40","difficulty":3,"kind":"mc","stem":"「소율이가 처음 쓴 시」를 고칠 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"김이 나는 모습이나 달큼한 맛처럼 그때 느낀 감각을 넣어 장면을 살린다","correct":true},{"t":"「맛있었다」를 「아주 아주 맛있었다」로 바꾼다","mis":"K4-1-u6-X29"},{"t":"행을 모두 붙여 한 줄로 쓴다","mis":"K4-1-u6-X32"},{"t":"제목을 지운다","mis":"K4-1-u6-X35"}],"explanation":["무엇이 빠졌나요?","감각적 표현","장면을 살려요."],"asset":{"type":"passage","lines":["오늘 군고구마를 먹었다.","군고구마가 맛있었다.","또 먹고 싶었다."],"title":"소율이가 처음 쓴 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_challenge#6','kor',4,1,'u6','L07','g4_1_kor_u6_L07_challenge','lesson_challenge','K4-1-u6-C31',3,'mc','auto','첫눈 경험을 시로 쓰려고 정리했어요. 「생각이나 느낌」에 들어갈 것은 무엇인가요?',ARRAY['K4-1-u6-X28','K4-1-u6-X27']::text[],false,'{"seq":6,"concept":"K4-1-u6-C31","difficulty":3,"kind":"mc","stem":"첫눈 경험을 시로 쓰려고 정리했어요. 「생각이나 느낌」에 들어갈 것은 무엇인가요?","options":[{"t":"내가 첫 발자국을 찍는 것 같았다","correct":true},{"t":"첫눈 온 아침 운동장을 걸었다","mis":"K4-1-u6-X28"},{"t":"뽀얗게 덮인 운동장","mis":"K4-1-u6-X28"},{"t":"운동장에 간 시각은 여덟 시였다","mis":"K4-1-u6-X27"}],"explanation":["겪은 일","감각적 표현","그때의 마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_challenge#7','kor',4,1,'u6','L07','g4_1_kor_u6_L07_challenge','lesson_challenge','K4-1-u6-C39',3,'mc','auto','「눈처럼 하얀」, 「꿀처럼 달콤한」 같은 말만 자주 쓰는 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X34','K4-1-u6-X23']::text[],false,'{"seq":7,"concept":"K4-1-u6-C39","difficulty":3,"kind":"mc","stem":"「눈처럼 하얀」, 「꿀처럼 달콤한」 같은 말만 자주 쓰는 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"「그때 너만 느낀 것을 떠올려서 새롭게 써 봐.」","correct":true},{"t":"「많이 쓰는 말이니 그대로 쓰는 게 제일 좋아.」","mis":"K4-1-u6-X34"},{"t":"「다른 사람이 쓴 시를 그대로 옮겨 써.」","mis":"K4-1-u6-X34"},{"t":"「비슷한 말을 열 개쯤 이어 붙여.」","mis":"K4-1-u6-X23"}],"explanation":["흔한 말","나만 느낀 것","새롭게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_challenge#8','kor',4,1,'u6','L07','g4_1_kor_u6_L07_challenge','lesson_challenge','K4-1-u6-C32',4,'essay','teacher','「아침에 창문을 여니 바람이 불었다.」를 감각적 표현 두 가지를 넣어 바꾸어 쓰고, 어떤 감각을 썼는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u6-C32","difficulty":4,"kind":"essay","stem":"「아침에 창문을 여니 바람이 불었다.」를 감각적 표현 두 가지를 넣어 바꾸어 쓰고, 어떤 감각을 썼는지 쓰세요.","answer_guide":{"answer":"예: 아침에 창문을 여니 서늘한 바람이 휘잉 볼을 스치고 지나갔다. — 「서늘한 · 볼을 스치고」는 촉각, 「휘잉」은 청각을 살렸다.","scoring_points":["감각적 표현 두 가지를 넣었는가","어떤 감각인지 바르게 썼는가","양이나 때만 더하지 않았는가"]},"explanation":["어떤 바람?","소리는?","닿는 느낌은?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_challenge#9','kor',4,1,'u6','L07','g4_1_kor_u6_L07_challenge','lesson_challenge','K4-1-u6-C37',4,'essay','teacher','「세라가 한 줄로 쓴 시」를 행을 나누어 다시 쓰고, 그렇게 나눈 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u6-C37","difficulty":4,"kind":"essay","stem":"「세라가 한 줄로 쓴 시」를 행을 나누어 다시 쓰고, 그렇게 나눈 까닭을 쓰세요.","answer_guide":{"answer":"예: 소나기 그친 운동장 / 물웅덩이마다 / 하늘이 / 한 조각씩 담겼다 — 「하늘이」를 따로 한 행으로 나누어 물웅덩이에 비친 하늘을 힘주어 나타냈다.","scoring_points":["여러 행으로 나누었는가","강조하고 싶은 말을 따로 행으로 나누었는가","나눈 까닭을 썼는가"]},"explanation":["어디를 힘주고 싶나요?","따로 한 행","까닭"],"asset":{"type":"passage","lines":["소나기 그친 운동장 물웅덩이마다 하늘이 한 조각씩 담겼다"],"title":"세라가 한 줄로 쓴 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L07_challenge#10','kor',4,1,'u6','L07','g4_1_kor_u6_L07_challenge','lesson_challenge','K4-1-u6-C30',4,'essay','teacher','내 경험 가운데 시로 쓰고 싶은 것을 하나 골라 겪은 일 · 감각적 표현 · 생각이나 느낌으로 정리해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u6-C30","difficulty":4,"kind":"essay","stem":"내 경험 가운데 시로 쓰고 싶은 것을 하나 골라 겪은 일 · 감각적 표현 · 생각이나 느낌으로 정리해 쓰세요.","answer_guide":{"answer":"예: 겪은 일 — 할머니 댁 마당에서 고추잠자리를 잡았다 / 감각적 표현 — 빨간 날개가 햇빛에 반짝, 손끝에 파르르 떨리는 날개 / 생각이나 느낌 — 놓아주니 내 마음도 함께 날아가는 것 같았다.","scoring_points":["몸으로 느낀 것이 또렷한 경험을 골랐는가","세 항목으로 정리했는가","감각적 표현을 넣었는가"]},"explanation":["겪은 일","감각적 표현","생각이나 느낌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_basic#1','kor',4,1,'u6','L09','g4_1_kor_u6_L09_basic','lesson_basic','K4-1-u6-C41',1,'mc','auto','「텐트 위로 떨어진 빗소리」에서 「후두둑후두둑」은 무엇을 나타낸 말인가요?',ARRAY['K4-1-u6-X20']::text[],false,'{"seq":1,"concept":"K4-1-u6-C41","difficulty":1,"kind":"mc","stem":"「텐트 위로 떨어진 빗소리」에서 「후두둑후두둑」은 무엇을 나타낸 말인가요?","options":[{"t":"굵은 빗방울이 텐트 지붕을 두드리는 소리","correct":true},{"t":"텐트 안의 축축한 느낌","mis":"K4-1-u6-X20"},{"t":"젖은 흙의 풀 냄새","mis":"K4-1-u6-X20"},{"t":"캠핑장의 넓은 모습","mis":"K4-1-u6-X20"}],"explanation":["③을 봐요.","귀로 들은 것","빗소리"],"asset":{"type":"passage","lines":["① 지난여름, 가족과 처음으로 캠핑을 갔다.","② 해가 지고 텐트에 누웠는데 갑자기 비가 내렸다.","③ 후두둑후두둑, 굵은 빗방울이 텐트 지붕을 두드렸다.","④ 천장을 만지니 축축한 기운이 손끝에 닿았다.","⑤ 젖은 흙에서는 진한 풀 냄새가 올라왔다.","⑥ 빗소리를 자장가처럼 들으며 나는 스르르 잠이 들었다."],"title":"텐트 위로 떨어진 빗소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_basic#2','kor',4,1,'u6','L09','g4_1_kor_u6_L09_basic','lesson_basic','K4-1-u6-C41',1,'match','auto','「텐트 위로 떨어진 빗소리」의 표현과 그 감각을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K4-1-u6-C41","difficulty":1,"kind":"match","stem":"「텐트 위로 떨어진 빗소리」의 표현과 그 감각을 알맞게 이으세요.","pairs":[{"l":"후두둑후두둑","r":"귀로 들은 소리"},{"l":"축축한 기운","r":"손에 닿은 느낌"},{"l":"진한 풀 냄새","r":"코로 맡은 냄새"}],"mis":"K4-1-u6-X20","explanation":["귀","손","코"],"asset":{"type":"passage","lines":["① 지난여름, 가족과 처음으로 캠핑을 갔다.","② 해가 지고 텐트에 누웠는데 갑자기 비가 내렸다.","③ 후두둑후두둑, 굵은 빗방울이 텐트 지붕을 두드렸다.","④ 천장을 만지니 축축한 기운이 손끝에 닿았다.","⑤ 젖은 흙에서는 진한 풀 냄새가 올라왔다.","⑥ 빗소리를 자장가처럼 들으며 나는 스르르 잠이 들었다."],"title":"텐트 위로 떨어진 빗소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_basic#3','kor',4,1,'u6','L09','g4_1_kor_u6_L09_basic','lesson_basic','K4-1-u6-C42',1,'mc','auto','경험을 글로 쓰기 전에 정리할 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X36']::text[],false,'{"seq":3,"concept":"K4-1-u6-C42","difficulty":1,"kind":"mc","stem":"경험을 글로 쓰기 전에 정리할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"그때 보거나 들은 것과 생각이나 느낌","correct":true},{"t":"글자 수 세기","mis":"K4-1-u6-X36"},{"t":"공책 쪽수 세기","mis":"K4-1-u6-X36"},{"t":"글씨 색깔 정하기","mis":"K4-1-u6-X36"}],"explanation":["글을 쓰는 데 도움이 되는 것","보고 들은 것","마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
