INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_basic#7','kor',4,1,'u6','L09','g4_1_kor_u6_L09_basic','lesson_basic','K4-1-u6-C45',2,'mc','auto','「어느 친구가 쓴 글」에서 가장 아쉬운 점은 무엇인가요?',ARRAY['K4-1-u6-X35','K4-1-u6-X38']::text[],false,'{"seq":7,"concept":"K4-1-u6-C45","difficulty":2,"kind":"mc","stem":"「어느 친구가 쓴 글」에서 가장 아쉬운 점은 무엇인가요?","options":[{"t":"보고 들은 것과 마음이 구체적으로 없다","correct":true},{"t":"겪은 일이 하나도 없다","mis":"K4-1-u6-X35"},{"t":"문장이 너무 길다","mis":"K4-1-u6-X35"},{"t":"제목이 없다","mis":"K4-1-u6-X38"}],"explanation":["비가 어떻게 왔나요?","그때 마음은?","구체적으로"],"asset":{"type":"passage","lines":["캠핑을 갔다. 비가 왔다. 잠을 잤다. 재미있었다."],"title":"어느 친구가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
