INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_basic#9','kor',4,1,'u6','L09','g4_1_kor_u6_L09_basic','lesson_basic','K4-1-u6-C47',2,'mc','auto','경험을 글로 쓰면 좋은 점은 무엇인가요?',ARRAY['K4-1-u6-X40']::text[],false,'{"seq":9,"concept":"K4-1-u6-C47","difficulty":2,"kind":"mc","stem":"경험을 글로 쓰면 좋은 점은 무엇인가요?","options":[{"t":"그날의 나를 돌아보고 오래 기억할 수 있다","correct":true},{"t":"숙제를 빨리 끝낼 수 있다","mis":"K4-1-u6-X40"},{"t":"나와는 상관없는 일을 배울 수 있다","mis":"K4-1-u6-X40"},{"t":"글자를 많이 쓰는 연습만 된다","mis":"K4-1-u6-X40"}],"explanation":["그날의 나","돌아보기","오래 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_basic#10','kor',4,1,'u6','L09','g4_1_kor_u6_L09_basic','lesson_basic','K4-1-u6-C46',3,'mc','auto','친구의 경험 글을 듣고 나눌 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X41','K4-1-u6-X25']::text[],false,'{"seq":10,"concept":"K4-1-u6-C46","difficulty":3,"kind":"mc","stem":"친구의 경험 글을 듣고 나눌 말로 알맞은 것은 무엇인가요?","options":[{"t":"「빗소리를 후두둑후두둑으로 나타내서 나도 그 소리가 들리는 것 같았어.」","correct":true},{"t":"「글이 몇 줄인지 세어 봤어.」","mis":"K4-1-u6-X41"},{"t":"「글씨가 작아서 별로야.」","mis":"K4-1-u6-X41"},{"t":"「나랑 경험이 달라서 틀렸어.」","mis":"K4-1-u6-X25"}],"explanation":["어떤 감각을 살렸나요?","그 표현","좋은 까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_challenge#1','kor',4,1,'u6','L09','g4_1_kor_u6_L09_challenge','lesson_challenge','K4-1-u6-C42',2,'mc','auto','「서진이의 글」에서 「일이 일어난 까닭」에 해당하는 것은 무엇인가요?',ARRAY['K4-1-u6-X05']::text[],false,'{"seq":1,"concept":"K4-1-u6-C42","difficulty":2,"kind":"mc","stem":"「서진이의 글」에서 「일이 일어난 까닭」에 해당하는 것은 무엇인가요?","options":[{"t":"엄마가 늦게 오셔서","correct":true},{"t":"냄비 속 물이 끓어올라서","mis":"K4-1-u6-X05"},{"t":"매콤한 냄새가 퍼져서","mis":"K4-1-u6-X05"},{"t":"마음이 뿌듯해서","mis":"K4-1-u6-X05"}],"explanation":["왜 라면을 끓였나요?","①을 봐요.","까닭"],"asset":{"type":"passage","lines":["① 토요일 저녁, 엄마가 늦게 오셔서 아빠와 둘이 저녁을 차리기로 했다.","② 냄비 속 물이 보글보글 끓어오르자 면과 수프를 넣었다.","③ 매콤한 냄새가 부엌 가득 퍼졌다.","④ 후루룩 한 입 먹으니 뜨거운 국물이 혀끝을 톡 쏘았다.","⑤ 내 손으로 만든 첫 요리라 마음이 뿌듯했다."],"title":"서진이의 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
