INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_challenge#7','kor',4,1,'u6','L09','g4_1_kor_u6_L09_challenge','lesson_challenge','K4-1-u6-C46',3,'mc','auto','친구 글을 듣고 감각적 표현을 찾아 말할 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X41','K4-1-u6-X25']::text[],false,'{"seq":7,"concept":"K4-1-u6-C46","difficulty":3,"kind":"mc","stem":"친구 글을 듣고 감각적 표현을 찾아 말할 때 알맞은 것은 무엇인가요?","options":[{"t":"어떤 감각을 살려 썼는지 짚고 그 표현이 좋은 까닭을 말한다","correct":true},{"t":"글씨가 바른지만 말한다","mis":"K4-1-u6-X41"},{"t":"글이 긴지 짧은지만 말한다","mis":"K4-1-u6-X41"},{"t":"나와 다르게 느낀 부분은 틀렸다고 말한다","mis":"K4-1-u6-X25"}],"explanation":["어떤 감각?","어떤 표현?","좋은 까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_challenge#8','kor',4,1,'u6','L09','g4_1_kor_u6_L09_challenge','lesson_challenge','K4-1-u6-C45',4,'essay','teacher','「나래의 일기」에 그때 보고 들은 것과 마음을 감각적 표현으로 넣어 다시 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u6-C45","difficulty":4,"kind":"essay","stem":"「나래의 일기」에 그때 보고 들은 것과 마음을 감각적 표현으로 넣어 다시 쓰세요.","answer_guide":{"answer":"예: 운동회 날, 출발 신호가 「탕!」 울리자 나는 힘껏 달렸다. 운동장 모래가 발밑에서 사각사각 밀렸고, 친구들 응원 소리가 귀를 가득 채웠다. 이어달리기에서 바통을 넘겨받을 때 손바닥이 땀으로 미끈거렸다. 숨이 턱까지 찼지만 끝까지 달려서 뿌듯했다.","scoring_points":["보거나 들은 것을 감각적 표현으로 넣었는가","그때의 마음을 썼는가","「했다」만 늘어놓지 않았는가"]},"explanation":["무엇이 보였나요?","무엇이 들렸나요?","마음은?"],"asset":{"type":"passage","lines":["운동회를 했다.","달리기를 했다.","이어달리기도 했다.","재미있었다."],"title":"나래의 일기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_challenge#9','kor',4,1,'u6','L09','g4_1_kor_u6_L09_challenge','lesson_challenge','K4-1-u6-C42',4,'essay','teacher','내 경험 하나를 골라 겪은 일 · 일이 일어난 까닭 · 보거나 들은 것 · 감각적 표현 · 생각이나 느낌으로 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u6-C42","difficulty":4,"kind":"essay","stem":"내 경험 하나를 골라 겪은 일 · 일이 일어난 까닭 · 보거나 들은 것 · 감각적 표현 · 생각이나 느낌으로 정리해 쓰세요.","answer_guide":{"answer":"예: 겪은 일 — 동생과 눈사람을 만들었다 / 까닭 — 밤새 눈이 많이 와서 / 보거나 들은 것 — 하얀 마당, 동생의 웃음소리 / 감각적 표현 — 장갑 사이로 스미는 시린 눈, 뽀드득 굴러가는 눈덩이 / 생각이나 느낌 — 손은 시렸지만 마음은 따뜻했다.","scoring_points":["다섯 항목을 모두 썼는가","까닭이 겪은 일과 맞는가","감각적 표현을 넣었는가"]},"explanation":["무슨 일 · 왜","보고 들은 것","마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L09_challenge#10','kor',4,1,'u6','L09','g4_1_kor_u6_L09_challenge','lesson_challenge','K4-1-u6-C43',4,'essay','teacher','오늘 날씨를 「맑음 · 흐림」 대신 감각적 표현을 넣어 두 가지로 쓰고, 각각 어떤 감각을 살렸는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u6-C43","difficulty":4,"kind":"essay","stem":"오늘 날씨를 「맑음 · 흐림」 대신 감각적 표현을 넣어 두 가지로 쓰고, 각각 어떤 감각을 살렸는지 쓰세요.","answer_guide":{"answer":"예: 은행잎이 노란 비처럼 흩날린 날 — 시각을 살렸다. / 바람이 옷깃 사이로 서늘하게 파고든 날 — 촉각을 살렸다.","scoring_points":["감각적 표현을 넣은 날씨를 두 가지 썼는가","살린 감각을 바르게 썼는가","그날의 느낌이 드러나는가"]},"explanation":["본 것","느낀 것","두 가지"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L11_basic#1','kor',4,1,'u6','L11','g4_1_kor_u6_L11_basic','lesson_basic','K4-1-u6-C48',1,'match','auto','원인과 결과 말하기 놀이에서 원인 카드와 결과 카드를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K4-1-u6-C48","difficulty":1,"kind":"match","stem":"원인과 결과 말하기 놀이에서 원인 카드와 결과 카드를 알맞게 이으세요.","pairs":[{"l":"물을 엎질렀다","r":"공책이 흠뻑 젖었다"},{"l":"새싹 화분을 햇볕 드는 창가로 옮겼다","r":"싹이 쑥 자랐다"},{"l":"신발 끈이 풀렸다","r":"달리다가 넘어졌다"}],"mis":"K4-1-u6-X05","explanation":["먼저 있었던 일","그 뒤에 생긴 일","짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
