INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L11_basic#7','kor',4,1,'u6','L11','g4_1_kor_u6_L11_basic','lesson_basic','K4-1-u6-C50',2,'mc','auto','감각적 표현이 담긴 시를 소개할 때 함께 말하면 좋은 것은 무엇인가요?',ARRAY['K4-1-u6-X44']::text[],false,'{"seq":7,"concept":"K4-1-u6-C50","difficulty":2,"kind":"mc","stem":"감각적 표현이 담긴 시를 소개할 때 함께 말하면 좋은 것은 무엇인가요?","options":[{"t":"어떤 감각으로 무엇을 나타냈는지","correct":true},{"t":"시에 쓰인 글자 수","mis":"K4-1-u6-X44"},{"t":"시집의 두께","mis":"K4-1-u6-X44"},{"t":"시집의 값","mis":"K4-1-u6-X44"}],"explanation":["감각적 표현 공부","어떤 감각?","무엇을?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L11_basic#8','kor',4,1,'u6','L11','g4_1_kor_u6_L11_basic','lesson_basic','K4-1-u6-C51',2,'ox','auto','「되고」, 「되니」처럼 쓸 때에도 「돼고」, 「돼니」로 써요.',ARRAY['K4-1-u6-X46']::text[],false,'{"seq":8,"concept":"K4-1-u6-C51","difficulty":2,"kind":"ox","stem":"「되고」, 「되니」처럼 쓸 때에도 「돼고」, 「돼니」로 써요.","answer":"X","reason_options":[{"t":"「돼」는 「되어」가 줄어든 말이라 「되어」로 바꿀 수 없는 자리에는 「되」를 쓰기 때문에","correct":true},{"t":"「돼」가 언제나 맞는 글자이기 때문에","mis":"K4-1-u6-X46"}],"mis":"K4-1-u6-X46","explanation":["되어고?","말이 안 돼요.","그래서 되고"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
