INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L11_basic#10','kor',4,1,'u6','L11','g4_1_kor_u6_L11_basic','lesson_basic','K4-1-u6-C54',3,'mc','auto','이 단원에서 배운 것을 바르게 정리한 것은 무엇인가요?',ARRAY['K4-1-u6-X48','K4-1-u6-X01']::text[],false,'{"seq":10,"concept":"K4-1-u6-C54","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 것을 바르게 정리한 것은 무엇인가요?","options":[{"t":"경험을 원인과 결과로 정리해 말하고, 감각적 표현으로 시와 글에 담는다","correct":true},{"t":"원인과 결과만 알면 감각적 표현은 필요 없다","mis":"K4-1-u6-X48"},{"t":"지나간 일은 말과 글로 남길 필요가 없다","mis":"K4-1-u6-X48"},{"t":"이 단원에서는 분수와 그래프를 배웠다","mis":"K4-1-u6-X01"}],"explanation":["말로","글로","두 가지 모두"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
