INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L11_challenge#8','kor',4,1,'u6','L11','g4_1_kor_u6_L11_challenge','lesson_challenge','K4-1-u6-C48',4,'essay','teacher','카드 「창문을 열어 두었다」와 「책상 위 종이가 날아갔다」를 「그래서」로 한 번, 「왜냐하면 … 때문이다」로 한 번 이어 말하는 문장을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u6-C48","difficulty":4,"kind":"essay","stem":"카드 「창문을 열어 두었다」와 「책상 위 종이가 날아갔다」를 「그래서」로 한 번, 「왜냐하면 … 때문이다」로 한 번 이어 말하는 문장을 쓰세요.","answer_guide":{"answer":"예: 창문을 열어 두었다. 그래서 책상 위 종이가 날아갔다. / 책상 위 종이가 날아갔다. 왜냐하면 창문을 열어 두었기 때문이다.","scoring_points":["「그래서」 앞에 원인을 썼는가","「왜냐하면 … 때문이다」를 짝지어 썼는가","원인과 결과를 바르게 놓았는가"]},"explanation":["원인 먼저","결과 먼저","두 가지로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L11_challenge#9','kor',4,1,'u6','L11','g4_1_kor_u6_L11_challenge','lesson_challenge','K4-1-u6-C52',4,'essay','teacher','「바닷가 모래사장」을 다섯 감각 가운데 세 가지로 나타내는 표현을 쓰고, 각각 어떤 감각인지 밝히세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u6-C52","difficulty":4,"kind":"essay","stem":"「바닷가 모래사장」을 다섯 감각 가운데 세 가지로 나타내는 표현을 쓰고, 각각 어떤 감각인지 밝히세요.","answer_guide":{"answer":"예: 시각 — 모래가 햇빛에 금가루처럼 반짝인다. / 청각 — 파도가 철썩철썩 모래를 쓸어 간다. / 촉각 — 맨발에 닿는 모래가 따끈하고 보드랍다.","scoring_points":["세 가지 감각으로 썼는가","감각을 바르게 밝혔는가","대상에 어울리는 표현인가"]},"explanation":["보이는 것","들리는 것","닿는 것"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_L11_challenge#10','kor',4,1,'u6','L11','g4_1_kor_u6_L11_challenge','lesson_challenge','K4-1-u6-C50',4,'essay','teacher','「수박 자르는 날」을 친구들에게 소개하는 말을 쓰세요. 어떤 감각으로 무엇을 나타냈는지와 인상 깊은 부분과 그 까닭을 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u6-C50","difficulty":4,"kind":"essay","stem":"「수박 자르는 날」을 친구들에게 소개하는 말을 쓰세요. 어떤 감각으로 무엇을 나타냈는지와 인상 깊은 부분과 그 까닭을 넣으세요.","answer_guide":{"answer":"예: 이 시는 「쩌억」으로 수박이 갈라지는 소리를, 「빨간 여름」으로 수박 속 색깔을 나타냈어요. 저는 「시원한 소나기가 입안에 쏟아진다」가 가장 인상 깊었어요. 왜냐하면 수박을 한 입 먹을 때 시원함이 그대로 느껴졌기 때문이에요.","scoring_points":["어떤 감각으로 무엇을 나타냈는지 썼는가","인상 깊은 부분을 골랐는가","그 까닭을 썼는가"]},"explanation":["어떤 감각?","인상 깊은 부분","까닭"],"asset":{"type":"passage","lines":["칼끝이 닿자","쩌억,","빨간 여름이 갈라진다","까만 씨앗은","밤하늘에 남은 별","한 입 베어 물면","시원한 소나기가","입안에 쏟아진다"],"title":"수박 자르는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
