INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#9','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C6',2,'mc','auto','「태민이의 연」에서 연줄이 끊어진 원인은 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X04']::text[],false,'{"seq":9,"concept":"K4-1-u6-C6","difficulty":2,"kind":"mc","stem":"「태민이의 연」에서 연줄이 끊어진 원인은 무엇인가요?","options":[{"t":"바람이 갑자기 세게 불었기 때문이다","correct":true},{"t":"연이 미루나무에 걸렸기 때문이다","mis":"K4-1-u6-X05"},{"t":"토요일이었기 때문이다","mis":"K4-1-u6-X04"},{"t":"아저씨가 지나가셨기 때문이다","mis":"K4-1-u6-X04"}],"explanation":["②를 봐요.","바람","원인"],"asset":{"type":"passage","lines":["① 토요일에 태민이는 강둑에서 연을 날렸다.","② 바람이 갑자기 세게 불어 연줄이 툭 끊어졌다.","③ 줄 끊긴 연은 날아가 높은 미루나무에 걸렸다.","④ 지나가던 이웃 아저씨가 긴 장대로 연을 내려 주셨다.","⑤ 태민이는 고마운 마음에 아저씨께 감사 쪽지를 썼다."],"title":"태민이의 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#10','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C7',2,'mc','auto','「소율이의 강낭콩」에서 결과이면서 또 다른 일의 원인인 것은 무엇인가요?',ARRAY['K4-1-u6-X06','K4-1-u6-X04']::text[],false,'{"seq":10,"concept":"K4-1-u6-C7","difficulty":2,"kind":"mc","stem":"「소율이의 강낭콩」에서 결과이면서 또 다른 일의 원인인 것은 무엇인가요?","options":[{"t":"강낭콩 잎이 축 늘어져 있었다","correct":true},{"t":"강낭콩 당번이 되었다","mis":"K4-1-u6-X06"},{"t":"며칠 뒤 잎이 다시 일어섰다","mis":"K4-1-u6-X06"},{"t":"월요일이 되었다","mis":"K4-1-u6-X04"}],"explanation":["왜 늘어졌나요?","늘어져서 한 일은?","둘 다"],"asset":{"type":"passage","lines":["① 소율이는 교실 창가에서 기르는 강낭콩 당번이 되었다.","② 소율이는 주말 동안 물 주는 것을 깜빡 잊었다.","③ 월요일에 보니 강낭콩 잎이 축 늘어져 있었다.","④ 소율이는 물을 듬뿍 주고 날마다 당번 표에 표시하기로 했다.","⑤ 며칠 뒤 잎이 다시 파릇파릇 일어섰다."],"title":"소율이의 강낭콩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#11','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C10',2,'mc','auto','결과를 먼저 말하고 까닭을 뒤에 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X09','K4-1-u6-X05','K4-1-u6-X07']::text[],false,'{"seq":11,"concept":"K4-1-u6-C10","difficulty":2,"kind":"mc","stem":"결과를 먼저 말하고 까닭을 뒤에 말한 것은 무엇인가요?","options":[{"t":"「강낭콩 잎이 시들었어. 왜냐하면 물 주는 것을 잊었기 때문이야.」","correct":true},{"t":"「물 주는 것을 잊었어. 그래서 강낭콩 잎이 시들었어.」","mis":"K4-1-u6-X09"},{"t":"「강낭콩 잎이 시들었어. 그래서 물 주는 것을 잊었어.」","mis":"K4-1-u6-X05"},{"t":"「강낭콩 잎이 시들었어. 그런데 물을 잊었어.」","mis":"K4-1-u6-X07"}],"explanation":["결과 먼저","왜냐하면","때문이야"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#12','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C25',2,'mc','auto','「소나기」에서 소리를 나타낸 표현은 무엇인가요?',ARRAY['K4-1-u6-X21','K4-1-u6-X20']::text[],false,'{"seq":12,"concept":"K4-1-u6-C25","difficulty":2,"kind":"mc","stem":"「소나기」에서 소리를 나타낸 표현은 무엇인가요?","options":[{"t":"토독토독","correct":true},{"t":"물웅덩이마다","mis":"K4-1-u6-X21"},{"t":"해님이","mis":"K4-1-u6-X21"},{"t":"반짝반짝","mis":"K4-1-u6-X20"}],"explanation":["귀로","빗소리","토독토독"],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#13','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C40',2,'mc','auto','「비가 왔다. / 비가 그쳤다. / 좋았다.」라고 쓴 시에서 가장 아쉬운 점은 무엇인가요?',ARRAY['K4-1-u6-X35']::text[],false,'{"seq":13,"concept":"K4-1-u6-C40","difficulty":2,"kind":"mc","stem":"「비가 왔다. / 비가 그쳤다. / 좋았다.」라고 쓴 시에서 가장 아쉬운 점은 무엇인가요?","options":[{"t":"감각적 표현이 없어 장면이 떠오르지 않는다","correct":true},{"t":"행이 너무 많다","mis":"K4-1-u6-X35"},{"t":"겪은 일이 없다","mis":"K4-1-u6-X35"},{"t":"제목이 길다","mis":"K4-1-u6-X35"}],"explanation":["어떤 비?","어떤 소리?","감각적 표현"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#14','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C19',2,'mc','auto','친구가 경험을 말할 때 알맞은 태도는 무엇인가요?',ARRAY['K4-1-u6-X17']::text[],false,'{"seq":14,"concept":"K4-1-u6-C19","difficulty":2,"kind":"mc","stem":"친구가 경험을 말할 때 알맞은 태도는 무엇인가요?","options":[{"t":"친구 얼굴을 보며 듣고, 궁금한 것은 다 들은 뒤에 묻는다","correct":true},{"t":"궁금하면 바로 끼어들어 묻는다","mis":"K4-1-u6-X17"},{"t":"내 차례만 기다리며 딴생각을 한다","mis":"K4-1-u6-X17"},{"t":"짝과 장난을 친다","mis":"K4-1-u6-X17"}],"explanation":["얼굴을 보며","끝까지","다 들은 뒤에"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#15','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C29',2,'mc','auto','시를 읽고 반응을 나눌 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X25','K4-1-u6-X26']::text[],false,'{"seq":15,"concept":"K4-1-u6-C29","difficulty":2,"kind":"mc","stem":"시를 읽고 반응을 나눌 때 알맞은 것은 무엇인가요?","options":[{"t":"인상 깊은 표현과 그 까닭을 들어 내 느낌을 말한다","correct":true},{"t":"친구와 느낌이 다르면 틀렸다고 말한다","mis":"K4-1-u6-X25"},{"t":"시의 글자 수를 센다","mis":"K4-1-u6-X26"},{"t":"시가 적힌 종이 색을 말한다","mis":"K4-1-u6-X26"}],"explanation":["표현","까닭","내 느낌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#16','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C42',2,'mc','auto','경험을 글로 쓰기 전에 정리할 것을 바르게 모은 것은 무엇인가요?',ARRAY['K4-1-u6-X36','K4-1-u6-X38']::text[],false,'{"seq":16,"concept":"K4-1-u6-C42","difficulty":2,"kind":"mc","stem":"경험을 글로 쓰기 전에 정리할 것을 바르게 모은 것은 무엇인가요?","options":[{"t":"겪은 일 · 일이 일어난 까닭 · 보거나 들은 것 · 감각적 표현 · 생각이나 느낌","correct":true},{"t":"글자 수 · 쪽수 · 글씨 색깔","mis":"K4-1-u6-X36"},{"t":"겪은 일 · 글자 수 · 날짜","mis":"K4-1-u6-X36"},{"t":"제목 · 쪽수 · 시간","mis":"K4-1-u6-X38"}],"explanation":["무슨 일 · 왜","보고 들은 것","마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#17','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C17',3,'mc','auto','「소율이의 강낭콩」에서 잎이 다시 일어서는 데 꼭 필요했던 일은 무엇인가요?',ARRAY['K4-1-u6-X15']::text[],false,'{"seq":17,"concept":"K4-1-u6-C17","difficulty":3,"kind":"mc","stem":"「소율이의 강낭콩」에서 잎이 다시 일어서는 데 꼭 필요했던 일은 무엇인가요?","options":[{"t":"소율이가 물을 듬뿍 주고 날마다 챙긴 것","correct":true},{"t":"월요일이 된 것","mis":"K4-1-u6-X15"},{"t":"창가에서 기른 것","mis":"K4-1-u6-X15"},{"t":"잎이 늘어진 것을 보기만 한 것","mis":"K4-1-u6-X15"}],"explanation":["일어서려면?","물","④를 봐요."],"asset":{"type":"passage","lines":["① 소율이는 교실 창가에서 기르는 강낭콩 당번이 되었다.","② 소율이는 주말 동안 물 주는 것을 깜빡 잊었다.","③ 월요일에 보니 강낭콩 잎이 축 늘어져 있었다.","④ 소율이는 물을 듬뿍 주고 날마다 당번 표에 표시하기로 했다.","⑤ 며칠 뒤 잎이 다시 파릇파릇 일어섰다."],"title":"소율이의 강낭콩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#18','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C32',3,'mc','auto','「바람이 불었다.」를 감각적으로 바꾼 것은 무엇인가요?',ARRAY['K4-1-u6-X29']::text[],false,'{"seq":18,"concept":"K4-1-u6-C32","difficulty":3,"kind":"mc","stem":"「바람이 불었다.」를 감각적으로 바꾼 것은 무엇인가요?","options":[{"t":"차가운 바람이 휘잉 볼을 스쳤다.","correct":true},{"t":"바람이 많이 불었다.","mis":"K4-1-u6-X29"},{"t":"오후에 바람이 불었다.","mis":"K4-1-u6-X29"},{"t":"바람이 또 불었다.","mis":"K4-1-u6-X29"}],"explanation":["어떤 바람?","소리 · 느낌","감각을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#19','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C37',3,'mc','auto','「소나기」에서 「토독토독」과 「반짝반짝」을 각각 한 행으로 따로 쓴 까닭은 무엇인가요?',ARRAY['K4-1-u6-X32','K4-1-u6-X31']::text[],false,'{"seq":19,"concept":"K4-1-u6-C37","difficulty":3,"kind":"mc","stem":"「소나기」에서 「토독토독」과 「반짝반짝」을 각각 한 행으로 따로 쓴 까닭은 무엇인가요?","options":[{"t":"빗소리와 반짝이는 모습을 힘주어 나타내려고","correct":true},{"t":"시를 길어 보이게 하려고","mis":"K4-1-u6-X32"},{"t":"연을 나누려고","mis":"K4-1-u6-X31"},{"t":"쓸 말이 없어서","mis":"K4-1-u6-X32"}],"explanation":["따로 한 행","힘주어","소리와 모습"],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#20','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C45',3,'mc','auto','「지호의 글」이 생생하게 느껴지는 까닭은 무엇인가요?',ARRAY['K4-1-u6-X39','K4-1-u6-X36','K4-1-u6-X38']::text[],false,'{"seq":20,"concept":"K4-1-u6-C45","difficulty":3,"kind":"mc","stem":"「지호의 글」이 생생하게 느껴지는 까닭은 무엇인가요?","options":[{"t":"바람 · 눈가루 · 손가락 · 코코아를 여러 감각으로 나타내고 마음까지 담았기 때문이다","correct":true},{"t":"있었던 일만 차례로 적었기 때문이다","mis":"K4-1-u6-X39"},{"t":"글자 수가 많기 때문이다","mis":"K4-1-u6-X36"},{"t":"제목이 길기 때문이다","mis":"K4-1-u6-X38"}],"explanation":["여러 감각","마음까지","생생해요."],"asset":{"type":"passage","lines":["① 겨울 방학에 사촌 형과 눈썰매장에 갔다.","② 썰매가 언덕을 내려가자 찬 바람이 볼을 쌩쌩 스쳤다.","③ 하얀 눈가루가 반짝이며 흩날렸다.","④ 썰매에서 내리자 장갑 속 손가락이 꽁꽁 얼어 있었다.","⑤ 매점에서 마신 코코아가 달콤하고 따끈했다.","⑥ 추웠지만 형과 함께 웃었던 그날이 자꾸 떠오른다."],"title":"지호의 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#21','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C51',3,'mc','auto','바르게 쓴 문장은 무엇인가요? (들어가는 일)',ARRAY['K4-1-u6-X45']::text[],false,'{"seq":21,"concept":"K4-1-u6-C51","difficulty":3,"kind":"mc","stem":"바르게 쓴 문장은 무엇인가요? (들어가는 일)","options":[{"t":"이제 들어가도 돼요.","correct":true},{"t":"이제 들어가도 되요.","mis":"K4-1-u6-X45"},{"t":"이제 들어가도 됬어요.","mis":"K4-1-u6-X45"},{"t":"이제 들어가도 돼여.","mis":"K4-1-u6-X45"}],"explanation":["되어요?","줄이면","돼요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#22','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C54',3,'mc','auto','이 단원에서 배운 두 가지를 생활에서 실천한 것은 무엇인가요?',ARRAY['K4-1-u6-X48','K4-1-u6-X01']::text[],false,'{"seq":22,"concept":"K4-1-u6-C54","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 두 가지를 생활에서 실천한 것은 무엇인가요?","options":[{"t":"겪은 일을 까닭까지 말하고, 일기에 감각적 표현을 넣어 쓴다","correct":true},{"t":"까닭은 빼고 결과만 말한다","mis":"K4-1-u6-X48"},{"t":"일기는 「재미있었다」로만 끝낸다","mis":"K4-1-u6-X48"},{"t":"분수 계산을 연습한다","mis":"K4-1-u6-X01"}],"explanation":["말로","글로","두 가지 모두"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#23','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C16',4,'essay','teacher','「소율이의 강낭콩」을 원인과 결과의 사슬로 정리하고, 「그래서」를 넣어 친구에게 말하듯 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u6-C16","difficulty":4,"kind":"essay","stem":"「소율이의 강낭콩」을 원인과 결과의 사슬로 정리하고, 「그래서」를 넣어 친구에게 말하듯 쓰세요.","answer_guide":{"answer":"예: 물 주는 것을 잊음 → 잎이 늘어짐 → 물을 듬뿍 주고 날마다 챙김 → 잎이 다시 일어섬. 「주말에 강낭콩에 물 주는 걸 잊었어. 그래서 잎이 축 늘어졌어. 그래서 물을 듬뿍 주고 날마다 챙겼더니 잎이 다시 파릇파릇 일어섰어.」","scoring_points":["사슬을 차례대로 정리했는가","「그래서」로 원인과 결과를 이었는가","결과가 다시 원인이 되는 것이 드러나는가"]},"explanation":["물을 잊음","늘어짐","다시 일어섬"],"asset":{"type":"passage","lines":["① 소율이는 교실 창가에서 기르는 강낭콩 당번이 되었다.","② 소율이는 주말 동안 물 주는 것을 깜빡 잊었다.","③ 월요일에 보니 강낭콩 잎이 축 늘어져 있었다.","④ 소율이는 물을 듬뿍 주고 날마다 당번 표에 표시하기로 했다.","⑤ 며칠 뒤 잎이 다시 파릇파릇 일어섰다."],"title":"소율이의 강낭콩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#24','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C40',4,'essay','teacher','「비가 왔다. 비가 그쳤다. 좋았다.」를 감각적 표현을 넣어 시로 고쳐 쓰고, 행을 알맞게 나누세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u6-C40","difficulty":4,"kind":"essay","stem":"「비가 왔다. 비가 그쳤다. 좋았다.」를 감각적 표현을 넣어 시로 고쳐 쓰고, 행을 알맞게 나누세요.","answer_guide":{"answer":"예: 후드득후드득 / 창문을 두드리던 비가 / 뚝 / 멈추자 / 젖은 운동장에 / 햇살이 반짝 / 내 마음도 반짝","scoring_points":["감각적 표현을 넣었는가","행을 알맞게 나누었는가","생각이나 느낌을 담았는가"]},"explanation":["어떤 소리?","어떤 모습?","내 마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_a#25','kor',4,1,'u6','','g4_1_kor_u6_review_a','unit_review','K4-1-u6-C45',4,'essay','teacher','「지호의 글」에서 감각적 표현 세 가지를 찾아 어떤 감각인지 쓰고, 이 글을 읽고 든 느낌을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u6-C45","difficulty":4,"kind":"essay","stem":"「지호의 글」에서 감각적 표현 세 가지를 찾아 어떤 감각인지 쓰고, 이 글을 읽고 든 느낌을 쓰세요.","answer_guide":{"answer":"예: 「찬 바람이 볼을 쌩쌩 스쳤다」 — 촉각, 「하얀 눈가루가 반짝이며 흩날렸다」 — 시각, 「코코아가 달콤하고 따끈했다」 — 미각. 글을 읽으니 나도 눈썰매장에 있는 것처럼 볼이 시린 느낌이 들었다.","scoring_points":["감각적 표현 세 가지를 찾았는가","감각을 바르게 썼는가","읽고 든 느낌을 썼는가"]},"explanation":["②","③","⑤"],"asset":{"type":"passage","lines":["① 겨울 방학에 사촌 형과 눈썰매장에 갔다.","② 썰매가 언덕을 내려가자 찬 바람이 볼을 쌩쌩 스쳤다.","③ 하얀 눈가루가 반짝이며 흩날렸다.","④ 썰매에서 내리자 장갑 속 손가락이 꽁꽁 얼어 있었다.","⑤ 매점에서 마신 코코아가 달콤하고 따끈했다.","⑥ 추웠지만 형과 함께 웃었던 그날이 자꾸 떠오른다."],"title":"지호의 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
