INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#2','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C9',1,'mc','auto','「왜냐하면」과 짝을 이루어 문장을 맺는 말은 무엇인가요?',ARRAY['K4-1-u6-X08']::text[],false,'{"seq":2,"concept":"K4-1-u6-C9","difficulty":1,"kind":"mc","stem":"「왜냐하면」과 짝을 이루어 문장을 맺는 말은 무엇인가요?","options":[{"t":"때문이다","correct":true},{"t":"그래서이다","mis":"K4-1-u6-X08"},{"t":"그런데이다","mis":"K4-1-u6-X08"},{"t":"그리고이다","mis":"K4-1-u6-X08"}],"explanation":["왜냐하면 …","… 때문이다","짝"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
