INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#9','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C21',2,'mc','auto','「3층 복도 소식」에서 복도에 물이 고인 원인은 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X04']::text[],false,'{"seq":9,"concept":"K4-1-u6-C21","difficulty":2,"kind":"mc","stem":"「3층 복도 소식」에서 복도에 물이 고인 원인은 무엇인가요?","options":[{"t":"창문이 열려 있어 비가 들이쳤기 때문이다","correct":true},{"t":"학생들이 다른 계단으로 갔기 때문이다","mis":"K4-1-u6-X05"},{"t":"아침이었기 때문이다","mis":"K4-1-u6-X04"},{"t":"3층이기 때문이다","mis":"K4-1-u6-X04"}],"explanation":["창문","비","들이쳤어요."],"asset":{"type":"passage","lines":["밤사이 3층 복도 창문이 열려 있었다.","새벽에 내린 비가 창문으로 들이쳐 복도에 물이 고였다.","아침에 3층 복도를 막아, 학생들은 다른 계단으로 돌아서 교실에 갔다."],"title":"3층 복도 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#10','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C17',2,'mc','auto','「연을 날렸다 → 연줄이 끊어졌다 → ( ? ) → 아저씨가 장대로 연을 내려 주셨다」의 빈 곳에 알맞은 일은 무엇인가요?',ARRAY['K4-1-u6-X14','K4-1-u6-X15']::text[],false,'{"seq":10,"concept":"K4-1-u6-C17","difficulty":2,"kind":"mc","stem":"「연을 날렸다 → 연줄이 끊어졌다 → ( ? ) → 아저씨가 장대로 연을 내려 주셨다」의 빈 곳에 알맞은 일은 무엇인가요?","options":[{"t":"연이 날아가 미루나무에 걸렸다","correct":true},{"t":"감사 쪽지를 썼다","mis":"K4-1-u6-X14"},{"t":"강둑에 꽃이 피었다","mis":"K4-1-u6-X15"},{"t":"연을 새로 샀다","mis":"K4-1-u6-X15"}],"explanation":["끊어져서?","내려 주신 까닭","가운데 고리"],"asset":{"type":"passage","lines":["① 토요일에 태민이는 강둑에서 연을 날렸다.","② 바람이 갑자기 세게 불어 연줄이 툭 끊어졌다.","③ 줄 끊긴 연은 날아가 높은 미루나무에 걸렸다.","④ 지나가던 이웃 아저씨가 긴 장대로 연을 내려 주셨다.","⑤ 태민이는 고마운 마음에 아저씨께 감사 쪽지를 썼다."],"title":"태민이의 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#11','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C11',2,'mc','auto','「바람이 세게 불어 우산이 뒤집히고, 모자가 날아가고, 나뭇잎이 떨어졌다.」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X10','K4-1-u6-X05','K4-1-u6-X03']::text[],false,'{"seq":11,"concept":"K4-1-u6-C11","difficulty":2,"kind":"mc","stem":"「바람이 세게 불어 우산이 뒤집히고, 모자가 날아가고, 나뭇잎이 떨어졌다.」를 바르게 말한 것은 무엇인가요?","options":[{"t":"하나의 원인으로 여러 결과가 생겼다","correct":true},{"t":"결과는 하나만 맞고 나머지는 틀렸다","mis":"K4-1-u6-X10"},{"t":"모자가 날아간 것이 바람이 분 원인이다","mis":"K4-1-u6-X05"},{"t":"원인이 없는 문장이다","mis":"K4-1-u6-X03"}],"explanation":["원인은?","바람","결과는 셋"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#12','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C25',2,'mc','auto','「소나기」에서 눈에 보이는 모습을 나타낸 표현은 무엇인가요?',ARRAY['K4-1-u6-X20','K4-1-u6-X21']::text[],false,'{"seq":12,"concept":"K4-1-u6-C25","difficulty":2,"kind":"mc","stem":"「소나기」에서 눈에 보이는 모습을 나타낸 표현은 무엇인가요?","options":[{"t":"반짝반짝","correct":true},{"t":"토독토독","mis":"K4-1-u6-X20"},{"t":"골목","mis":"K4-1-u6-X21"},{"t":"하나씩","mis":"K4-1-u6-X21"}],"explanation":["눈으로","빛나는 모습","반짝반짝"],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#13','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C45',2,'mc','auto','「놀이공원에 갔다. 놀이 기구를 탔다. 재미있었다.」를 더 좋은 경험 글로 고치는 방법은 무엇인가요?',ARRAY['K4-1-u6-X39','K4-1-u6-X35']::text[],false,'{"seq":13,"concept":"K4-1-u6-C45","difficulty":2,"kind":"mc","stem":"「놀이공원에 갔다. 놀이 기구를 탔다. 재미있었다.」를 더 좋은 경험 글로 고치는 방법은 무엇인가요?","options":[{"t":"그때 보고 들은 것과 마음을 감각적 표현으로 자세히 쓴다","correct":true},{"t":"「재미있었다」를 세 번 쓴다","mis":"K4-1-u6-X39"},{"t":"문장을 모두 지운다","mis":"K4-1-u6-X35"},{"t":"날짜만 더 쓴다","mis":"K4-1-u6-X39"}],"explanation":["무엇을 보았나요?","무엇을 들었나요?","마음은?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#14','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C18',2,'mc','auto','경험을 말하는 모습으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X16','K4-1-u6-X02','K4-1-u6-X14']::text[],false,'{"seq":14,"concept":"K4-1-u6-C18","difficulty":2,"kind":"mc","stem":"경험을 말하는 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"일어난 차례대로 이어 주는 말을 넣어 또박또박 말한다","correct":true},{"t":"외운 것을 빠르게 쏟아 낸다","mis":"K4-1-u6-X16"},{"t":"까닭은 빼고 짧게 말한다","mis":"K4-1-u6-X02"},{"t":"생각나는 대로 뒤섞어 말한다","mis":"K4-1-u6-X14"}],"explanation":["차례대로","이어 주는 말","또박또박"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#15','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C26',2,'mc','auto','「소나기」의 「물웅덩이마다 / 반짝반짝 / 해님이 하나씩 떠 있다」에서 떠오르는 장면은 무엇인가요?',ARRAY['K4-1-u6-X50']::text[],false,'{"seq":15,"concept":"K4-1-u6-C26","difficulty":2,"kind":"mc","stem":"「소나기」의 「물웅덩이마다 / 반짝반짝 / 해님이 하나씩 떠 있다」에서 떠오르는 장면은 무엇인가요?","options":[{"t":"비가 그친 뒤 물웅덩이마다 해가 비쳐 반짝이는 장면","correct":true},{"t":"하늘에 해가 여러 개 뜬 장면","mis":"K4-1-u6-X50"},{"t":"물웅덩이에 해님이 빠진 장면","mis":"K4-1-u6-X50"},{"t":"밤하늘 별을 세는 장면","mis":"K4-1-u6-X50"}],"explanation":["물웅덩이에","비친 해","반짝반짝"],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#16','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C49',2,'mc','auto','한 대상을 감각적으로 나타내는 것에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X43','K4-1-u6-X20']::text[],false,'{"seq":16,"concept":"K4-1-u6-C49","difficulty":2,"kind":"mc","stem":"한 대상을 감각적으로 나타내는 것에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"한 대상도 모양 · 소리 · 냄새 · 맛 · 촉감 등 여러 감각으로 나타낼 수 있다","correct":true},{"t":"한 대상은 한 가지 감각으로만 나타낸다","mis":"K4-1-u6-X43"},{"t":"색깔만 감각적 표현이다","mis":"K4-1-u6-X43"},{"t":"맛은 감각이 아니다","mis":"K4-1-u6-X20"}],"explanation":["사과를 떠올려요.","반들반들 · 아삭","여러 감각"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#17','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C2',3,'mc','auto','「소율이의 강낭콩」의 일을 친구에게 말할 때 가장 잘 전해지는 말은 무엇인가요?',ARRAY['K4-1-u6-X02','K4-1-u6-X05','K4-1-u6-X08']::text[],false,'{"seq":17,"concept":"K4-1-u6-C2","difficulty":3,"kind":"mc","stem":"「소율이의 강낭콩」의 일을 친구에게 말할 때 가장 잘 전해지는 말은 무엇인가요?","options":[{"t":"「주말에 물 주는 걸 잊었어. 그래서 잎이 축 늘어졌지 뭐야.」","correct":true},{"t":"「잎이 늘어졌어. 끝.」","mis":"K4-1-u6-X02"},{"t":"「잎이 늘어졌어. 그래서 물을 잊었어.」","mis":"K4-1-u6-X05"},{"t":"「잎이 늘어졌어. 왜냐하면 물을 잊었어서 그래서야.」","mis":"K4-1-u6-X08"}],"explanation":["원인","그래서","결과"],"asset":{"type":"passage","lines":["① 소율이는 교실 창가에서 기르는 강낭콩 당번이 되었다.","② 소율이는 주말 동안 물 주는 것을 깜빡 잊었다.","③ 월요일에 보니 강낭콩 잎이 축 늘어져 있었다.","④ 소율이는 물을 듬뿍 주고 날마다 당번 표에 표시하기로 했다.","⑤ 며칠 뒤 잎이 다시 파릇파릇 일어섰다."],"title":"소율이의 강낭콩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#18','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C32',3,'mc','auto','「국이 뜨거웠다.」를 감각적으로 바꾼 것은 무엇인가요?',ARRAY['K4-1-u6-X29']::text[],false,'{"seq":18,"concept":"K4-1-u6-C32","difficulty":3,"kind":"mc","stem":"「국이 뜨거웠다.」를 감각적으로 바꾼 것은 무엇인가요?","options":[{"t":"국에서 김이 모락모락 오르고, 한 숟가락 뜨니 입안이 후끈했다.","correct":true},{"t":"국이 아주 뜨거웠다.","mis":"K4-1-u6-X29"},{"t":"저녁에 국이 뜨거웠다.","mis":"K4-1-u6-X29"},{"t":"국이 두 그릇이나 뜨거웠다.","mis":"K4-1-u6-X29"}],"explanation":["보이는 김","입안의 느낌","감각을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#19','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C38',3,'mc','auto','「소나기」의 앞 네 행과 뒤 네 행을 연으로 나누는 까닭은 무엇인가요?',ARRAY['K4-1-u6-X33','K4-1-u6-X31']::text[],false,'{"seq":19,"concept":"K4-1-u6-C38","difficulty":3,"kind":"mc","stem":"「소나기」의 앞 네 행과 뒤 네 행을 연으로 나누는 까닭은 무엇인가요?","options":[{"t":"비가 내리는 장면에서 비가 그친 장면으로 바뀌기 때문이다","correct":true},{"t":"네 행마다 꼭 연을 나누어야 하기 때문이다","mis":"K4-1-u6-X33"},{"t":"행과 연은 같은 것이기 때문이다","mis":"K4-1-u6-X31"},{"t":"연은 아무 데서나 나누기 때문이다","mis":"K4-1-u6-X33"}],"explanation":["앞 네 행","뒤 네 행","장면이 바뀌어요."],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#20','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C42',3,'mc','auto','「지호의 글」에서 「생각이나 느낌」에 해당하는 문장은 무엇인가요?',ARRAY['K4-1-u6-X28']::text[],false,'{"seq":20,"concept":"K4-1-u6-C42","difficulty":3,"kind":"mc","stem":"「지호의 글」에서 「생각이나 느낌」에 해당하는 문장은 무엇인가요?","options":[{"t":"추웠지만 형과 함께 웃었던 그날이 자꾸 떠오른다","correct":true},{"t":"겨울 방학에 사촌 형과 눈썰매장에 갔다","mis":"K4-1-u6-X28"},{"t":"하얀 눈가루가 반짝이며 흩날렸다","mis":"K4-1-u6-X28"},{"t":"썰매가 언덕을 내려갔다","mis":"K4-1-u6-X28"}],"explanation":["⑥을 봐요.","그때의 마음","떠오른다"],"asset":{"type":"passage","lines":["① 겨울 방학에 사촌 형과 눈썰매장에 갔다.","② 썰매가 언덕을 내려가자 찬 바람이 볼을 쌩쌩 스쳤다.","③ 하얀 눈가루가 반짝이며 흩날렸다.","④ 썰매에서 내리자 장갑 속 손가락이 꽁꽁 얼어 있었다.","⑤ 매점에서 마신 코코아가 달콤하고 따끈했다.","⑥ 추웠지만 형과 함께 웃었던 그날이 자꾸 떠오른다."],"title":"지호의 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#21','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C51',3,'mc','auto','바르게 쓴 문장은 무엇인가요? (장래 희망)',ARRAY['K4-1-u6-X46','K4-1-u6-X45']::text[],false,'{"seq":21,"concept":"K4-1-u6-C51","difficulty":3,"kind":"mc","stem":"바르게 쓴 문장은 무엇인가요? (장래 희망)","options":[{"t":"나는 커서 수의사가 되고 싶다.","correct":true},{"t":"나는 커서 수의사가 돼고 싶다.","mis":"K4-1-u6-X46"},{"t":"나는 커서 수의사가 됫고 싶다.","mis":"K4-1-u6-X45"},{"t":"나는 커서 수의사가 되어고 싶다.","mis":"K4-1-u6-X46"}],"explanation":["되어고?","어색해요.","되고"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#22','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C49',3,'mc','auto','주사위 놀이에서 「바람」과 「촉감」이 나왔어요. 알맞게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X20','K4-1-u6-X21','K4-1-u6-X43']::text[],false,'{"seq":22,"concept":"K4-1-u6-C49","difficulty":3,"kind":"mc","stem":"주사위 놀이에서 「바람」과 「촉감」이 나왔어요. 알맞게 말한 것은 무엇인가요?","options":[{"t":"「바람이 목덜미를 서늘하게 쓰다듬는다.」","correct":true},{"t":"「바람이 휘잉휘잉 분다.」","mis":"K4-1-u6-X20"},{"t":"「바람이 두 번 분다.」","mis":"K4-1-u6-X21"},{"t":"「바람은 소리로만 나타낼 수 있다.」","mis":"K4-1-u6-X43"}],"explanation":["대상은 바람","감각은 촉감","닿는 느낌"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#23','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C21',4,'essay','teacher','「3층 복도 소식」에서 원인과 결과를 두 쌍 찾아 쓰고, 그 가운데 하나를 「왜냐하면 … 때문이다」를 넣은 문장으로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u6-C21","difficulty":4,"kind":"essay","stem":"「3층 복도 소식」에서 원인과 결과를 두 쌍 찾아 쓰고, 그 가운데 하나를 「왜냐하면 … 때문이다」를 넣은 문장으로 쓰세요.","answer_guide":{"answer":"예: 창문이 열려 있었다 → 비가 들이쳐 복도에 물이 고였다. / 복도에 물이 고였다 → 복도를 막아 학생들이 다른 계단으로 돌아갔다. 「학생들은 다른 계단으로 돌아갔다. 왜냐하면 3층 복도에 물이 고여 복도를 막았기 때문이다.」","scoring_points":["원인과 결과 두 쌍을 바르게 찾았는가","「왜냐하면 … 때문이다」를 짝지어 썼는가","결과를 먼저 말했는가"]},"explanation":["창문","물","돌아감"],"asset":{"type":"passage","lines":["밤사이 3층 복도 창문이 열려 있었다.","새벽에 내린 비가 창문으로 들이쳐 복도에 물이 고였다.","아침에 3층 복도를 막아, 학생들은 다른 계단으로 돌아서 교실에 갔다."],"title":"3층 복도 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#24','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C38',4,'essay','teacher','「소나기」의 두 연이 각각 어떤 장면을 나타내는지 쓰고, 두 장면에서 감각적 표현을 하나씩 찾아 어떤 감각인지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u6-C38","difficulty":4,"kind":"essay","stem":"「소나기」의 두 연이 각각 어떤 장면을 나타내는지 쓰고, 두 장면에서 감각적 표현을 하나씩 찾아 어떤 감각인지 쓰세요.","answer_guide":{"answer":"예: 1연은 소나기가 우산 위로 쏟아지는 장면, 2연은 소나기가 그친 골목의 물웅덩이에 해가 비친 장면이다. 1연의 「토독토독」은 청각, 2연의 「반짝반짝」은 시각이다.","scoring_points":["두 연의 장면을 바르게 썼는가","연마다 감각적 표현을 찾았는가","감각을 바르게 썼는가"]},"explanation":["1연","2연","감각"],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_b#25','kor',4,1,'u6','','g4_1_kor_u6_review_b','unit_review','K4-1-u6-C47',4,'essay','teacher','오늘 있었던 일 하나를 골라 보고 들은 것을 감각적 표현으로 넣고, 그때의 내 마음까지 담아 세 문장 이상으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u6-C47","difficulty":4,"kind":"essay","stem":"오늘 있었던 일 하나를 골라 보고 들은 것을 감각적 표현으로 넣고, 그때의 내 마음까지 담아 세 문장 이상으로 쓰세요.","answer_guide":{"answer":"예: 점심시간에 급식실 문을 열자 고소한 참기름 냄새가 코끝에 솔솔 스며들었다. 따끈한 밥 위에 나물을 올려 비벼 먹으니 고소한 맛이 입안 가득 퍼졌다. 맛있게 먹고 나니 오후 수업도 힘이 났다.","scoring_points":["겪은 일을 골랐는가","감각적 표현을 넣었는가","그때의 마음을 담았는가"]},"explanation":["겪은 일","보고 들은 것","마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#1','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C6',1,'mc','auto','「소율이의 강낭콩」에서 강낭콩 잎이 축 늘어진 원인은 무엇인가요?',ARRAY['K4-1-u6-X04','K4-1-u6-X05']::text[],false,'{"seq":1,"concept":"K4-1-u6-C6","difficulty":1,"kind":"mc","stem":"「소율이의 강낭콩」에서 강낭콩 잎이 축 늘어진 원인은 무엇인가요?","options":[{"t":"주말 동안 물 주는 것을 잊었기 때문이다","correct":true},{"t":"교실 창가에서 기르기 때문이다","mis":"K4-1-u6-X04"},{"t":"월요일이었기 때문이다","mis":"K4-1-u6-X04"},{"t":"당번 표에 표시했기 때문이다","mis":"K4-1-u6-X05"}],"explanation":["②를 봐요.","물","잊었어요."],"asset":{"type":"passage","lines":["① 소율이는 교실 창가에서 기르는 강낭콩 당번이 되었다.","② 소율이는 주말 동안 물 주는 것을 깜빡 잊었다.","③ 월요일에 보니 강낭콩 잎이 축 늘어져 있었다.","④ 소율이는 물을 듬뿍 주고 날마다 당번 표에 표시하기로 했다.","⑤ 며칠 뒤 잎이 다시 파릇파릇 일어섰다."],"title":"소율이의 강낭콩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#2','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C8',1,'mc','auto','「밤새 눈이 많이 내렸다. ( ) 아침에 운동장이 하얗게 덮였다.」의 빈 곳에 알맞은 말은 무엇인가요?',ARRAY['K4-1-u6-X07','K4-1-u6-X08']::text[],false,'{"seq":2,"concept":"K4-1-u6-C8","difficulty":1,"kind":"mc","stem":"「밤새 눈이 많이 내렸다. ( ) 아침에 운동장이 하얗게 덮였다.」의 빈 곳에 알맞은 말은 무엇인가요?","options":[{"t":"그래서","correct":true},{"t":"그런데","mis":"K4-1-u6-X07"},{"t":"왜냐하면","mis":"K4-1-u6-X08"},{"t":"하지만","mis":"K4-1-u6-X07"}],"explanation":["앞은 원인","뒤는 결과","그래서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#3','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C23',1,'mc','auto','냄새를 느끼는 감각은 무엇인가요?',ARRAY['K4-1-u6-X20']::text[],false,'{"seq":3,"concept":"K4-1-u6-C23","difficulty":1,"kind":"mc","stem":"냄새를 느끼는 감각은 무엇인가요?","options":[{"t":"후각(냄새)","correct":true},{"t":"미각(맛)","mis":"K4-1-u6-X20"},{"t":"청각(소리)","mis":"K4-1-u6-X20"},{"t":"시각(모양 · 색깔)","mis":"K4-1-u6-X20"}],"explanation":["코","맡는 것","후각"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#4','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C24',1,'mc','auto','「새콤한」에 담긴 감각은 무엇인가요?',ARRAY['K4-1-u6-X20']::text[],false,'{"seq":4,"concept":"K4-1-u6-C24","difficulty":1,"kind":"mc","stem":"「새콤한」에 담긴 감각은 무엇인가요?","options":[{"t":"미각(맛)","correct":true},{"t":"후각(냄새)","mis":"K4-1-u6-X20"},{"t":"청각(소리)","mis":"K4-1-u6-X20"},{"t":"시각(모양 · 색깔)","mis":"K4-1-u6-X20"}],"explanation":["새콤한 무엇?","맛","미각"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#5','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C35',1,'mc','auto','「소나기」는 모두 몇 행으로 되어 있나요?',ARRAY['K4-1-u6-X31']::text[],false,'{"seq":5,"concept":"K4-1-u6-C35","difficulty":1,"kind":"mc","stem":"「소나기」는 모두 몇 행으로 되어 있나요?","options":[{"t":"8행","correct":true},{"t":"2행","mis":"K4-1-u6-X31"},{"t":"4행","mis":"K4-1-u6-X31"},{"t":"1행","mis":"K4-1-u6-X31"}],"explanation":["한 줄씩","세어 봐요.","여덟 줄"],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#6','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C51',1,'mc','auto','「되었어요」를 줄여 쓴 말은 무엇인가요?',ARRAY['K4-1-u6-X45']::text[],false,'{"seq":6,"concept":"K4-1-u6-C51","difficulty":1,"kind":"mc","stem":"「되었어요」를 줄여 쓴 말은 무엇인가요?","options":[{"t":"됐어요","correct":true},{"t":"됬어요","mis":"K4-1-u6-X45"},{"t":"되았어요","mis":"K4-1-u6-X45"},{"t":"돼었어요","mis":"K4-1-u6-X45"}],"explanation":["되었어요","줄이면","됐어요"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#7','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C13',1,'mc','auto','원인과 결과로 말할 경험에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X11','K4-1-u6-X02']::text[],false,'{"seq":7,"concept":"K4-1-u6-C13","difficulty":1,"kind":"mc","stem":"원인과 결과로 말할 경험에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"작고 사소한 일이라도 괜찮다","correct":true},{"t":"특별한 여행만 말할 수 있다","mis":"K4-1-u6-X11"},{"t":"남이 겪은 일만 말해야 한다","mis":"K4-1-u6-X11"},{"t":"까닭이 없는 일이 더 좋다","mis":"K4-1-u6-X02"}],"explanation":["특별해야 하나요?","아니에요.","작은 일도"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#8','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C43',1,'mc','auto','그날의 소리를 담아 일기의 날씨를 쓴 것은 무엇인가요?',ARRAY['K4-1-u6-X37']::text[],false,'{"seq":8,"concept":"K4-1-u6-C43","difficulty":1,"kind":"mc","stem":"그날의 소리를 담아 일기의 날씨를 쓴 것은 무엇인가요?","options":[{"t":"바람이 귓가에서 휘잉휘잉 노래한 날","correct":true},{"t":"흐림","mis":"K4-1-u6-X37"},{"t":"보통","mis":"K4-1-u6-X37"},{"t":"어제와 같음","mis":"K4-1-u6-X37"}],"explanation":["그날의 소리","휘잉휘잉","느낌을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#9','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C6',2,'mc','auto','「텐트 위로 떨어진 빗소리」에서 글쓴이가 스르르 잠이 든 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X04','K4-1-u6-X05']::text[],false,'{"seq":9,"concept":"K4-1-u6-C6","difficulty":2,"kind":"mc","stem":"「텐트 위로 떨어진 빗소리」에서 글쓴이가 스르르 잠이 든 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"빗소리를 자장가처럼 들었기 때문이다","correct":true},{"t":"캠핑을 처음 갔기 때문이다","mis":"K4-1-u6-X04"},{"t":"젖은 흙에서 풀 냄새가 났기 때문이다","mis":"K4-1-u6-X04"},{"t":"잠이 들어서 빗소리가 났기 때문이다","mis":"K4-1-u6-X05"}],"explanation":["⑥을 봐요.","자장가처럼","까닭"],"asset":{"type":"passage","lines":["① 지난여름, 가족과 처음으로 캠핑을 갔다.","② 해가 지고 텐트에 누웠는데 갑자기 비가 내렸다.","③ 후두둑후두둑, 굵은 빗방울이 텐트 지붕을 두드렸다.","④ 천장을 만지니 축축한 기운이 손끝에 닿았다.","⑤ 젖은 흙에서는 진한 풀 냄새가 올라왔다.","⑥ 빗소리를 자장가처럼 들으며 나는 스르르 잠이 들었다."],"title":"텐트 위로 떨어진 빗소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#10','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C16',2,'mc','auto','「소율이의 강낭콩」의 일을 원인과 결과로 알맞게 이은 것은 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X04']::text[],false,'{"seq":10,"concept":"K4-1-u6-C16","difficulty":2,"kind":"mc","stem":"「소율이의 강낭콩」의 일을 원인과 결과로 알맞게 이은 것은 무엇인가요?","options":[{"t":"물 주는 것을 잊었다 → 잎이 축 늘어졌다","correct":true},{"t":"잎이 축 늘어졌다 → 물 주는 것을 잊었다","mis":"K4-1-u6-X05"},{"t":"잎이 다시 일어섰다 → 물을 듬뿍 주었다","mis":"K4-1-u6-X05"},{"t":"월요일이 되었다 → 잎이 늘어졌다","mis":"K4-1-u6-X04"}],"explanation":["무엇이 먼저?","까닭 → 일어난 일","화살표"],"asset":{"type":"passage","lines":["① 소율이는 교실 창가에서 기르는 강낭콩 당번이 되었다.","② 소율이는 주말 동안 물 주는 것을 깜빡 잊었다.","③ 월요일에 보니 강낭콩 잎이 축 늘어져 있었다.","④ 소율이는 물을 듬뿍 주고 날마다 당번 표에 표시하기로 했다.","⑤ 며칠 뒤 잎이 다시 파릇파릇 일어섰다."],"title":"소율이의 강낭콩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#11','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C10',2,'mc','auto','「운동장에 나가지 못했다. 왜냐하면 비가 세게 내렸기 때문이다.」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X09','K4-1-u6-X05','K4-1-u6-X08']::text[],false,'{"seq":11,"concept":"K4-1-u6-C10","difficulty":2,"kind":"mc","stem":"「운동장에 나가지 못했다. 왜냐하면 비가 세게 내렸기 때문이다.」를 바르게 말한 것은 무엇인가요?","options":[{"t":"결과를 먼저 말하고 원인을 뒤에 말했다","correct":true},{"t":"원인을 먼저 말하지 않아 틀린 말이다","mis":"K4-1-u6-X09"},{"t":"원인과 결과가 거꾸로 이어졌다","mis":"K4-1-u6-X05"},{"t":"이어 주는 말을 쓰지 않았다","mis":"K4-1-u6-X08"}],"explanation":["결과 먼저","까닭 뒤에","자연스러워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#12','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C41',2,'mc','auto','「지호의 글」에서 촉각을 나타낸 표현은 무엇인가요?',ARRAY['K4-1-u6-X20','K4-1-u6-X21']::text[],false,'{"seq":12,"concept":"K4-1-u6-C41","difficulty":2,"kind":"mc","stem":"「지호의 글」에서 촉각을 나타낸 표현은 무엇인가요?","options":[{"t":"장갑 속 손가락이 꽁꽁 얼어 있었다","correct":true},{"t":"하얀 눈가루가 반짝이며 흩날렸다","mis":"K4-1-u6-X20"},{"t":"사촌 형과 눈썰매장에 갔다","mis":"K4-1-u6-X21"},{"t":"그날이 자꾸 떠오른다","mis":"K4-1-u6-X21"}],"explanation":["닿는 느낌","꽁꽁","촉각"],"asset":{"type":"passage","lines":["① 겨울 방학에 사촌 형과 눈썰매장에 갔다.","② 썰매가 언덕을 내려가자 찬 바람이 볼을 쌩쌩 스쳤다.","③ 하얀 눈가루가 반짝이며 흩날렸다.","④ 썰매에서 내리자 장갑 속 손가락이 꽁꽁 얼어 있었다.","⑤ 매점에서 마신 코코아가 달콤하고 따끈했다.","⑥ 추웠지만 형과 함께 웃었던 그날이 자꾸 떠오른다."],"title":"지호의 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#13','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C28',2,'mc','auto','「노란 해바라기, 노란 나비, 노란 모자, 노란 대문」처럼 쓴 시에 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X24','K4-1-u6-X23','K4-1-u6-X19']::text[],false,'{"seq":13,"concept":"K4-1-u6-C28","difficulty":2,"kind":"mc","stem":"「노란 해바라기, 노란 나비, 노란 모자, 노란 대문」처럼 쓴 시에 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"「모습만 나오니 소리나 냄새처럼 실제로 느낀 다른 감각도 넣어 봐.」","correct":true},{"t":"「노란 것을 더 많이 늘어놓아 봐.」","mis":"K4-1-u6-X24"},{"t":"「감각적 표현은 많을수록 좋으니 아무거나 더 넣어.」","mis":"K4-1-u6-X23"},{"t":"「어려운 낱말로 바꿔 봐.」","mis":"K4-1-u6-X19"}],"explanation":["모습만","다른 감각도","실제로 느낀 것"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#14','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C20',2,'mc','auto','경험 말하기를 점검하는 물음으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X18','K4-1-u6-X16']::text[],false,'{"seq":14,"concept":"K4-1-u6-C20","difficulty":2,"kind":"mc","stem":"경험 말하기를 점검하는 물음으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「원인과 결과가 드러나게 말했나요?」","correct":true},{"t":"「누가 가장 길게 말했나요?」","mis":"K4-1-u6-X18"},{"t":"「목소리만 컸나요?」","mis":"K4-1-u6-X18"},{"t":"「가장 빨리 끝냈나요?」","mis":"K4-1-u6-X16"}],"explanation":["순서","원인과 결과","이어 주는 말"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#15','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C38',2,'mc','auto','「소나기」를 두 연으로 나눈다면 어디에서 나누는 것이 알맞은가요?',ARRAY['K4-1-u6-X33']::text[],false,'{"seq":15,"concept":"K4-1-u6-C38","difficulty":2,"kind":"mc","stem":"「소나기」를 두 연으로 나눈다면 어디에서 나누는 것이 알맞은가요?","options":[{"t":"「차가운 물방울이 손등에 톡」 다음","correct":true},{"t":"「토독토독」 다음","mis":"K4-1-u6-X33"},{"t":"「반짝반짝」 다음","mis":"K4-1-u6-X33"},{"t":"연을 나누지 않는다","mis":"K4-1-u6-X33"}],"explanation":["비가 올 때","비가 그친 뒤","장면이 바뀌는 곳"],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#16','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C48',2,'mc','auto','카드 「창문을 활짝 열었다」와 「시원한 바람이 들어왔다」를 알맞게 이어 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X07','K4-1-u6-X08']::text[],false,'{"seq":16,"concept":"K4-1-u6-C48","difficulty":2,"kind":"mc","stem":"카드 「창문을 활짝 열었다」와 「시원한 바람이 들어왔다」를 알맞게 이어 말한 것은 무엇인가요?","options":[{"t":"창문을 활짝 열었다. 그래서 시원한 바람이 들어왔다.","correct":true},{"t":"시원한 바람이 들어왔다. 그래서 창문을 활짝 열었다.","mis":"K4-1-u6-X05"},{"t":"창문을 활짝 열었다. 그런데 시원한 바람이 들어왔다.","mis":"K4-1-u6-X07"},{"t":"창문을 활짝 열었다. 왜냐하면 시원한 바람이 들어왔다.","mis":"K4-1-u6-X08"}],"explanation":["무엇이 먼저?","창문","그래서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#17','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C21',3,'mc','auto','「3층 복도 소식」에서 원인과 결과를 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X04']::text[],false,'{"seq":17,"concept":"K4-1-u6-C21","difficulty":3,"kind":"mc","stem":"「3층 복도 소식」에서 원인과 결과를 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"창문이 열려 있었다 → 비가 복도로 들이쳤다","correct":true},{"t":"학생들이 돌아서 갔다 → 복도에 물이 고였다","mis":"K4-1-u6-X05"},{"t":"아침이었다 → 복도를 막았다","mis":"K4-1-u6-X04"},{"t":"비가 들이쳤다 → 창문이 열렸다","mis":"K4-1-u6-X05"}],"explanation":["까닭 → 일어난 일","창문","비"],"asset":{"type":"passage","lines":["밤사이 3층 복도 창문이 열려 있었다.","새벽에 내린 비가 창문으로 들이쳐 복도에 물이 고였다.","아침에 3층 복도를 막아, 학생들은 다른 계단으로 돌아서 교실에 갔다."],"title":"3층 복도 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#18','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C33',3,'mc','auto','끝맺음을 다양하게 바꾸어 쓴 시로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X30','K4-1-u6-X29']::text[],false,'{"seq":18,"concept":"K4-1-u6-C33","difficulty":3,"kind":"mc","stem":"끝맺음을 다양하게 바꾸어 쓴 시로 알맞은 것은 무엇인가요?","options":[{"t":"바람이 분다 / 나뭇잎이 사르르 / 손을 흔드네","correct":true},{"t":"바람이 불었다 / 나뭇잎이 흔들렸다 / 나는 보았다","mis":"K4-1-u6-X30"},{"t":"바람이 불었다 / 바람이 불었다 / 바람이 불었다","mis":"K4-1-u6-X30"},{"t":"바람이 많이 불었다 / 아주 많이 불었다","mis":"K4-1-u6-X29"}],"explanation":["-었다만?","분다 · 흔드네","다양하게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#19','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C35',3,'mc','auto','행과 연에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X31','K4-1-u6-X33']::text[],false,'{"seq":19,"concept":"K4-1-u6-C35","difficulty":3,"kind":"mc","stem":"행과 연에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"행이 모여 연이 되고, 강조할 말은 행으로 나누고 장면이 바뀌면 연으로 나눈다","correct":true},{"t":"연이 모여 행이 된다","mis":"K4-1-u6-X31"},{"t":"행과 연은 같은 말이다","mis":"K4-1-u6-X31"},{"t":"연은 한 줄이 끝날 때마다 나눈다","mis":"K4-1-u6-X33"}],"explanation":["행 = 한 줄","연 = 덩어리","나누는 까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#20','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C47',3,'mc','auto','경험 글을 쓰는 동안 일어나는 일로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X40']::text[],false,'{"seq":20,"concept":"K4-1-u6-C47","difficulty":3,"kind":"mc","stem":"경험 글을 쓰는 동안 일어나는 일로 알맞은 것은 무엇인가요?","options":[{"t":"그때의 나를 돌아보며 내 마음을 알게 된다","correct":true},{"t":"나와 상관없는 일만 떠오른다","mis":"K4-1-u6-X40"},{"t":"숙제만 끝난다","mis":"K4-1-u6-X40"},{"t":"있었던 일을 모두 잊는다","mis":"K4-1-u6-X40"}],"explanation":["그날의 나","돌아보기","내 마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#21','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C51',3,'mc','auto','「돼」를 쓸지 「되」를 쓸지 알아보는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X45','K4-1-u6-X46']::text[],false,'{"seq":21,"concept":"K4-1-u6-C51","difficulty":3,"kind":"mc","stem":"「돼」를 쓸지 「되」를 쓸지 알아보는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"「되어」로 바꾸어 자연스러우면 「돼」, 어색하면 「되」를 쓴다","correct":true},{"t":"소리 나는 대로 아무거나 쓴다","mis":"K4-1-u6-X45"},{"t":"늘 「돼」를 쓴다","mis":"K4-1-u6-X46"},{"t":"늘 「되」를 쓴다","mis":"K4-1-u6-X45"}],"explanation":["되어로 바꿔 봐요.","자연스러우면 돼","어색하면 되"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#22','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C50',3,'mc','auto','「소나기」를 시화전에서 소개하는 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X44']::text[],false,'{"seq":22,"concept":"K4-1-u6-C50","difficulty":3,"kind":"mc","stem":"「소나기」를 시화전에서 소개하는 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「토독토독으로 빗소리를, 반짝반짝으로 물웅덩이의 해를 나타낸 점이 좋아요.」","correct":true},{"t":"「여덟 줄이라서 좋아요.」","mis":"K4-1-u6-X44"},{"t":"「종이가 두꺼워서 좋아요.」","mis":"K4-1-u6-X44"},{"t":"「제목이 세 글자라서 좋아요.」","mis":"K4-1-u6-X44"}],"explanation":["어떤 감각?","무엇을?","좋은 까닭"],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#23','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C11',4,'essay','teacher','하나의 원인으로 여러 결과가 생긴 예를 하나 들어, 그 원인과 결과들을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u6-C11","difficulty":4,"kind":"essay","stem":"하나의 원인으로 여러 결과가 생긴 예를 하나 들어, 그 원인과 결과들을 쓰세요.","answer_guide":{"answer":"예: 원인 — 밤새 눈이 많이 내렸다. / 결과 — 운동장이 하얗게 덮였다, 버스가 늦게 왔다, 친구들과 눈싸움을 했다.","scoring_points":["원인을 하나 썼는가","그 원인에서 생긴 결과를 둘 이상 썼는가","원인과 결과가 자연스럽게 이어지는가"]},"explanation":["원인 하나","결과 여럿","예를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#24','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C39',4,'essay','teacher','「나뭇잎」을 소재로 남이 자주 쓰는 표현이 아닌 나만의 감각적 표현을 넣어 세 행 이상의 짧은 시를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u6-C39","difficulty":4,"kind":"essay","stem":"「나뭇잎」을 소재로 남이 자주 쓰는 표현이 아닌 나만의 감각적 표현을 넣어 세 행 이상의 짧은 시를 쓰세요.","answer_guide":{"answer":"예: 바람이 지나가면 / 나뭇잎이 / 사락사락 / 작은 손뼉을 친다","scoring_points":["세 행 이상으로 썼는가","감각적 표현을 넣었는가","흔한 표현이 아닌 나만의 표현인가"]},"explanation":["내가 본 나뭇잎","들은 소리","새롭게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_c#25','kor',4,1,'u6','','g4_1_kor_u6_review_c','unit_review','K4-1-u6-C51',4,'essay','teacher','「되어」를 줄인 「돼」를 넣은 문장과 「되」를 넣은 문장을 하나씩 쓰고, 「되」와 「돼」를 가려 쓰는 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u6-C51","difficulty":4,"kind":"essay","stem":"「되어」를 줄인 「돼」를 넣은 문장과 「되」를 넣은 문장을 하나씩 쓰고, 「되」와 「돼」를 가려 쓰는 방법을 쓰세요.","answer_guide":{"answer":"예: 이제 집에 가도 돼. / 나는 커서 요리사가 되고 싶다. 「되어」로 바꾸어 자연스러우면 「돼」, 어색하면 「되」를 쓴다.","scoring_points":["「돼」를 바르게 넣은 문장을 썼는가","「되」를 바르게 넣은 문장을 썼는가","가려 쓰는 방법을 썼는가"]},"explanation":["되어로 바꿔 봐요.","자연스러우면 돼","어색하면 되"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#1','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C5',1,'mc','auto','「소율이의 강낭콩」에서 소율이가 물을 듬뿍 준 일의 결과는 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X04']::text[],false,'{"seq":1,"concept":"K4-1-u6-C5","difficulty":1,"kind":"mc","stem":"「소율이의 강낭콩」에서 소율이가 물을 듬뿍 준 일의 결과는 무엇인가요?","options":[{"t":"며칠 뒤 잎이 다시 파릇파릇 일어섰다","correct":true},{"t":"주말 동안 물 주는 것을 잊었다","mis":"K4-1-u6-X05"},{"t":"강낭콩 당번이 되었다","mis":"K4-1-u6-X04"},{"t":"월요일이 되었다","mis":"K4-1-u6-X04"}],"explanation":["물을 주었더니?","⑤를 봐요.","결과"],"asset":{"type":"passage","lines":["① 소율이는 교실 창가에서 기르는 강낭콩 당번이 되었다.","② 소율이는 주말 동안 물 주는 것을 깜빡 잊었다.","③ 월요일에 보니 강낭콩 잎이 축 늘어져 있었다.","④ 소율이는 물을 듬뿍 주고 날마다 당번 표에 표시하기로 했다.","⑤ 며칠 뒤 잎이 다시 파릇파릇 일어섰다."],"title":"소율이의 강낭콩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#2','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C9',1,'mc','auto','「오늘은 우산을 챙겼다. 왜냐하면 하늘이 잔뜩 흐렸기 ( ).」의 빈 곳에 알맞은 말은 무엇인가요?',ARRAY['K4-1-u6-X08']::text[],false,'{"seq":2,"concept":"K4-1-u6-C9","difficulty":1,"kind":"mc","stem":"「오늘은 우산을 챙겼다. 왜냐하면 하늘이 잔뜩 흐렸기 ( ).」의 빈 곳에 알맞은 말은 무엇인가요?","options":[{"t":"때문이다","correct":true},{"t":"그래서다","mis":"K4-1-u6-X08"},{"t":"그런데다","mis":"K4-1-u6-X08"},{"t":"하지만이다","mis":"K4-1-u6-X08"}],"explanation":["왜냐하면","때문이다","짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#3','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C23',1,'mc','auto','손발에 닿는 느낌을 느끼는 감각은 무엇인가요?',ARRAY['K4-1-u6-X20']::text[],false,'{"seq":3,"concept":"K4-1-u6-C23","difficulty":1,"kind":"mc","stem":"손발에 닿는 느낌을 느끼는 감각은 무엇인가요?","options":[{"t":"촉각(닿는 느낌)","correct":true},{"t":"미각(맛)","mis":"K4-1-u6-X20"},{"t":"시각(모양 · 색깔)","mis":"K4-1-u6-X20"},{"t":"청각(소리)","mis":"K4-1-u6-X20"}],"explanation":["손발","닿는 것","촉각"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
