INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#8','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C41',1,'mc','auto','감각적 표현을 쓸 수 있는 글에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X49','K4-1-u6-X22']::text[],false,'{"seq":8,"concept":"K4-1-u6-C41","difficulty":1,"kind":"mc","stem":"감각적 표현을 쓸 수 있는 글에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"시뿐 아니라 일기 같은 경험 글에서도 쓸 수 있다","correct":true},{"t":"시에서만 쓸 수 있다","mis":"K4-1-u6-X49"},{"t":"설명하는 글에서만 쓸 수 있다","mis":"K4-1-u6-X49"},{"t":"어디에도 쓰지 않는 것이 좋다","mis":"K4-1-u6-X22"}],"explanation":["시","일기","어디서나"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#9','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C5',2,'mc','auto','「지호의 글」에서 장갑 속 손가락이 꽁꽁 언 것은 무엇의 결과인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X04']::text[],false,'{"seq":9,"concept":"K4-1-u6-C5","difficulty":2,"kind":"mc","stem":"「지호의 글」에서 장갑 속 손가락이 꽁꽁 언 것은 무엇의 결과인가요?","options":[{"t":"찬 바람을 맞으며 눈썰매를 탄 것","correct":true},{"t":"코코아를 마신 것","mis":"K4-1-u6-X05"},{"t":"사촌 형이 웃은 것","mis":"K4-1-u6-X04"},{"t":"그날이 자꾸 떠오르는 것","mis":"K4-1-u6-X05"}],"explanation":["왜 얼었나요?","찬 바람","썰매"],"asset":{"type":"passage","lines":["① 겨울 방학에 사촌 형과 눈썰매장에 갔다.","② 썰매가 언덕을 내려가자 찬 바람이 볼을 쌩쌩 스쳤다.","③ 하얀 눈가루가 반짝이며 흩날렸다.","④ 썰매에서 내리자 장갑 속 손가락이 꽁꽁 얼어 있었다.","⑤ 매점에서 마신 코코아가 달콤하고 따끈했다.","⑥ 추웠지만 형과 함께 웃었던 그날이 자꾸 떠오른다."],"title":"지호의 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#10','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C7',2,'mc','auto','결과가 또 다른 일의 원인이 되는 것에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X06']::text[],false,'{"seq":10,"concept":"K4-1-u6-C7","difficulty":2,"kind":"mc","stem":"결과가 또 다른 일의 원인이 되는 것에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"하나의 일이 앞일의 결과이면서 뒷일의 원인이 될 수 있다","correct":true},{"t":"하나의 일은 원인이거나 결과 가운데 하나일 뿐이다","mis":"K4-1-u6-X06"},{"t":"원인은 늘 맨 처음 일 하나뿐이다","mis":"K4-1-u6-X06"},{"t":"결과는 다시 원인이 될 수 없다","mis":"K4-1-u6-X06"}],"explanation":["사슬","결과이면서 원인","이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
