INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#13','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C39',2,'mc','auto','나만의 표현을 찾아 쓴 것은 무엇인가요?',ARRAY['K4-1-u6-X34','K4-1-u6-X23']::text[],false,'{"seq":13,"concept":"K4-1-u6-C39","difficulty":2,"kind":"mc","stem":"나만의 표현을 찾아 쓴 것은 무엇인가요?","options":[{"t":"「갓 깎은 연필에서 나무 향이 솔솔 났다」처럼 내가 느낀 그대로 쓴 것","correct":true},{"t":"누구나 쓰는 말을 그대로 옮긴 것","mis":"K4-1-u6-X34"},{"t":"잘 알려진 시의 한 줄을 베낀 것","mis":"K4-1-u6-X34"},{"t":"느끼지 않은 것을 지어 넣은 것","mis":"K4-1-u6-X23"}],"explanation":["내가 느낀 것","새로운 표현","그대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#14','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C46',2,'mc','auto','친구 글을 듣고 감각적 표현을 찾아 말한 것은 무엇인가요?',ARRAY['K4-1-u6-X41','K4-1-u6-X25']::text[],false,'{"seq":14,"concept":"K4-1-u6-C46","difficulty":2,"kind":"mc","stem":"친구 글을 듣고 감각적 표현을 찾아 말한 것은 무엇인가요?","options":[{"t":"「소리를 살려 써서 그 장면이 귀에 들리는 것 같았어.」","correct":true},{"t":"「글씨가 예뻐.」","mis":"K4-1-u6-X41"},{"t":"「다섯 줄이야.」","mis":"K4-1-u6-X41"},{"t":"「내 경험과 달라서 틀렸어.」","mis":"K4-1-u6-X25"}],"explanation":["어떤 감각?","소리","살려 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#15','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C29',2,'mc','auto','「소나기」를 읽은 두 친구의 느낌이 서로 달라요. 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u6-X25']::text[],false,'{"seq":15,"concept":"K4-1-u6-C29","difficulty":2,"kind":"mc","stem":"「소나기」를 읽은 두 친구의 느낌이 서로 달라요. 알맞은 생각은 무엇인가요?","options":[{"t":"같은 시도 사람마다 느낌이 다를 수 있다","correct":true},{"t":"한 사람은 틀렸다","mis":"K4-1-u6-X25"},{"t":"더 길게 말한 느낌이 맞다","mis":"K4-1-u6-X25"},{"t":"선생님 느낌과 같아야 한다","mis":"K4-1-u6-X25"}],"explanation":["느낌은","저마다","달라요."],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#16','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C50',2,'mc','auto','시화전에서 시를 소개하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X44']::text[],false,'{"seq":16,"concept":"K4-1-u6-C50","difficulty":2,"kind":"mc","stem":"시화전에서 시를 소개하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"시를 소리 내어 읽고, 인상 깊은 부분과 그 까닭을 말한다","correct":true},{"t":"시집의 두께를 말한다","mis":"K4-1-u6-X44"},{"t":"시의 글자 수를 말한다","mis":"K4-1-u6-X44"},{"t":"시를 아무도 못 보게 접어 둔다","mis":"K4-1-u6-X44"}],"explanation":["읽고","인상 깊은 부분","까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#17','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C16',3,'mc','auto','「태민이의 연」을 원인과 결과의 사슬로 바르게 정리한 것은 무엇인가요?',ARRAY['K4-1-u6-X05','K4-1-u6-X14','K4-1-u6-X04']::text[],false,'{"seq":17,"concept":"K4-1-u6-C16","difficulty":3,"kind":"mc","stem":"「태민이의 연」을 원인과 결과의 사슬로 바르게 정리한 것은 무엇인가요?","options":[{"t":"바람이 셈 → 연줄이 끊어짐 → 나무에 걸림 → 아저씨가 내려 주심 → 감사 쪽지","correct":true},{"t":"감사 쪽지 → 아저씨가 내려 주심 → 나무에 걸림 → 연줄이 끊어짐 → 바람이 셈","mis":"K4-1-u6-X05"},{"t":"바람이 셈 → 나무에 걸림 → 감사 쪽지 → 연줄이 끊어짐 → 아저씨가 내려 주심","mis":"K4-1-u6-X14"},{"t":"토요일 → 강둑 → 미루나무 → 아저씨 → 쪽지","mis":"K4-1-u6-X04"}],"explanation":["까닭부터","차례대로","사슬"],"asset":{"type":"passage","lines":["① 토요일에 태민이는 강둑에서 연을 날렸다.","② 바람이 갑자기 세게 불어 연줄이 툭 끊어졌다.","③ 줄 끊긴 연은 날아가 높은 미루나무에 걸렸다.","④ 지나가던 이웃 아저씨가 긴 장대로 연을 내려 주셨다.","⑤ 태민이는 고마운 마음에 아저씨께 감사 쪽지를 썼다."],"title":"태민이의 연"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#18','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C34',3,'mc','auto','눈썰매 타는 장면을 여러 감각을 섞어 나타낸 것은 무엇인가요?',ARRAY['K4-1-u6-X21','K4-1-u6-X24']::text[],false,'{"seq":18,"concept":"K4-1-u6-C34","difficulty":3,"kind":"mc","stem":"눈썰매 타는 장면을 여러 감각을 섞어 나타낸 것은 무엇인가요?","options":[{"t":"하얀 언덕을 쌩 미끄러지면 찬 바람이 볼을 콕콕 찌른다","correct":true},{"t":"눈썰매를 세 번 탔다","mis":"K4-1-u6-X21"},{"t":"하얀 언덕, 하얀 눈, 하얀 모자","mis":"K4-1-u6-X24"},{"t":"그리고 아마도 눈썰매를 탔다","mis":"K4-1-u6-X21"}],"explanation":["하얀","쌩","콕콕"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#19','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C37',3,'mc','auto','「첫눈」에서 「뽀드득」만 따로 한 행으로 쓴 효과는 무엇인가요?',ARRAY['K4-1-u6-X32','K4-1-u6-X31']::text[],false,'{"seq":19,"concept":"K4-1-u6-C37","difficulty":3,"kind":"mc","stem":"「첫눈」에서 「뽀드득」만 따로 한 행으로 쓴 효과는 무엇인가요?","options":[{"t":"눈 밟는 소리가 귀에 크게 들리는 듯 힘이 실린다","correct":true},{"t":"시가 짧아진다","mis":"K4-1-u6-X32"},{"t":"연이 하나 더 생긴다","mis":"K4-1-u6-X31"},{"t":"글자 수가 맞추어진다","mis":"K4-1-u6-X32"}],"explanation":["뽀드득","따로 한 행","힘이 실려요."],"asset":{"type":"passage","lines":["밤새 하늘이 밀가루를","체에 쳤나 보다","운동장이","뽀얗게","덮였다","한 발 내디디니","뽀드득","새 발자국이 찍힌다"],"title":"첫눈"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#20','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C44',3,'mc','auto','「지호의 글」에 어울리는 제목으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X38']::text[],false,'{"seq":20,"concept":"K4-1-u6-C44","difficulty":3,"kind":"mc","stem":"「지호의 글」에 어울리는 제목으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"볼이 얼얼했던 눈썰매 날","correct":true},{"t":"겨울","mis":"K4-1-u6-X38"},{"t":"사촌 형의 장갑","mis":"K4-1-u6-X38"},{"t":"나의 글 1","mis":"K4-1-u6-X38"}],"explanation":["무슨 일?","어떤 느낌?","어울리게"],"asset":{"type":"passage","lines":["① 겨울 방학에 사촌 형과 눈썰매장에 갔다.","② 썰매가 언덕을 내려가자 찬 바람이 볼을 쌩쌩 스쳤다.","③ 하얀 눈가루가 반짝이며 흩날렸다.","④ 썰매에서 내리자 장갑 속 손가락이 꽁꽁 얼어 있었다.","⑤ 매점에서 마신 코코아가 달콤하고 따끈했다.","⑥ 추웠지만 형과 함께 웃었던 그날이 자꾸 떠오른다."],"title":"지호의 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#21','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C53',3,'mc','auto','「하늘」의 ㄹ처럼 받침으로 쓰인 자음자를 쓸 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u6-X47']::text[],false,'{"seq":21,"concept":"K4-1-u6-C53","difficulty":3,"kind":"mc","stem":"「하늘」의 ㄹ처럼 받침으로 쓰인 자음자를 쓸 때 알맞은 것은 무엇인가요?","options":[{"t":"첫소리 자리일 때와 크기 · 모양을 다르게 하여 글자에 어울리게 쓴다","correct":true},{"t":"첫소리 ㄹ과 똑같이 크게 쓴다","mis":"K4-1-u6-X47"},{"t":"받침은 칸 밖에 쓴다","mis":"K4-1-u6-X47"},{"t":"받침은 흐리게 써도 된다","mis":"K4-1-u6-X47"}],"explanation":["받침 자리","어울리게","크기 · 모양"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#22','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C48',3,'mc','auto','놀이에서 카드 「눈이 펑펑 내렸다」와 「연필심이 부러졌다」를 뽑았어요. 알맞게 한 것은 무엇인가요?',ARRAY['K4-1-u6-X42','K4-1-u6-X05']::text[],false,'{"seq":22,"concept":"K4-1-u6-C48","difficulty":3,"kind":"mc","stem":"놀이에서 카드 「눈이 펑펑 내렸다」와 「연필심이 부러졌다」를 뽑았어요. 알맞게 한 것은 무엇인가요?","options":[{"t":"자연스럽게 이어지지 않으니 카드를 다시 내려놓는다","correct":true},{"t":"「눈이 펑펑 내렸다. 그래서 연필심이 부러졌다.」라고 억지로 잇는다","mis":"K4-1-u6-X42"},{"t":"「연필심이 부러졌다. 그래서 눈이 펑펑 내렸다.」라고 잇는다","mis":"K4-1-u6-X05"},{"t":"아무 말 없이 카드를 가져간다","mis":"K4-1-u6-X42"}],"explanation":["이어지나요?","아니에요.","내려놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#23','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C13',4,'essay','teacher','최근에 겪은 작은 일 하나를 골라 원인과 결과가 드러나게 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u6-C13","difficulty":4,"kind":"essay","stem":"최근에 겪은 작은 일 하나를 골라 원인과 결과가 드러나게 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 어제 저녁 연필을 깎지 않고 잤다. 그래서 오늘 받아쓰기 시간에 연필심이 금방 닳았다. 짝이 연필을 빌려주어 무사히 끝냈다.","scoring_points":["작은 경험을 골랐는가","원인과 결과가 드러나는가","이어 주는 말을 알맞게 썼는가"]},"explanation":["작은 일","왜?","그래서"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#24','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C29',4,'essay','teacher','「소나기」를 읽고 가장 마음에 드는 부분을 골라, 그 까닭과 함께 내 느낌을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u6-C29","difficulty":4,"kind":"essay","stem":"「소나기」를 읽고 가장 마음에 드는 부분을 골라, 그 까닭과 함께 내 느낌을 쓰세요.","answer_guide":{"answer":"예: 「물웅덩이마다 / 반짝반짝 / 해님이 하나씩 떠 있다」가 가장 마음에 든다. 비 갠 뒤 웅덩이에 해가 비친 모습을 해님이 떠 있다고 해서 귀엽고 밝게 느껴졌기 때문이다. 나도 비 온 뒤 웅덩이를 들여다본 기억이 났다.","scoring_points":["시의 한 부분을 골랐는가","고른 까닭을 썼는가","내 생각이나 느낌을 썼는가"]},"explanation":["어느 부분?","왜?","내 느낌"],"asset":{"type":"passage","lines":["토독토독","우산 위로","소나기가 뛰어내린다","차가운 물방울이 손등에 톡","소나기 그친 골목","물웅덩이마다","반짝반짝","해님이 하나씩 떠 있다"],"title":"소나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u6_review_d#25','kor',4,1,'u6','','g4_1_kor_u6_review_d','unit_review','K4-1-u6-C54',4,'essay','teacher','이 단원에서 배운 것 가운데 앞으로 실천하고 싶은 일을 말하기에서 하나, 쓰기에서 하나 골라 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u6-C54","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 것 가운데 앞으로 실천하고 싶은 일을 말하기에서 하나, 쓰기에서 하나 골라 쓰세요.","answer_guide":{"answer":"예: 말하기에서는 친구에게 겪은 일을 말할 때 「왜냐하면 … 때문이야」로 까닭까지 함께 말하겠다. 쓰기에서는 일기를 쓸 때 날씨와 그날 들은 소리를 감각적 표현으로 한 가지씩 넣겠다.","scoring_points":["말하기 실천을 썼는가","쓰기 실천을 썼는가","배운 방법이 드러나는가"]},"explanation":["말로","글로","꾸준히"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
